contracts/AtlasHTLC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title AtlasHTLC
 * @notice Hash Time-Locked Contract for cross-chain atomic swaps on EVM chains.
 *
 * Supports native ETH and ERC-20 tokens.
 *
 * Function selectors (must match the SDK's evm.ts adapter):
 *   createHTLC:  0x4b2f336d
 *   claimHTLC:   0x84cc315c
 *   refundHTLC:  0x7249fbb6
 *   getHTLC:     0x905d22a5
 */

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract AtlasHTLC is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ─── Types ──────────────────────────────────────────────

    enum HTLCStatus {
        Pending,   // 0 — created, not yet funded (for ERC-20)
        Funded,    // 1 — funds locked
        Claimed,   // 2 — recipient claimed with secret
        Refunded,  // 3 — sender refunded after expiry
        Expired    // 4 — timelock passed, awaiting refund
    }

    struct HTLC {
        address sender;
        address recipient;
        address token;          // address(0) = native ETH
        uint256 amount;
        bytes32 hashLock;
        uint256 timeLock;       // Unix timestamp
        HTLCStatus status;
        bytes32 secret;         // Stored on claim
    }

    // ─── State ──────────────────────────────────────────────

    mapping(bytes32 => HTLC) public htlcs;
    uint256 public htlcCount;

    // ─── Events ─────────────────────────────────────────────

    event HTLCCreated(
        bytes32 indexed id,
        address indexed sender,
        address indexed recipient,
        address token,
        uint256 amount,
        bytes32 hashLock,
        uint256 timeLock
    );

    event HTLCClaimed(
        bytes32 indexed id,
        address indexed claimant,
        bytes32 secret
    );

    event HTLCRefunded(
        bytes32 indexed id,
        address indexed sender
    );

    // ─── Modifiers ──────────────────────────────────────────

    modifier htlcExists(bytes32 id) {
        require(htlcs[id].sender != address(0), "HTLC does not exist");
        _;
    }

    // ─── Create ─────────────────────────────────────────────

    /**
     * @notice Create a new HTLC.
     * @param recipient   Address that can claim with the secret
     * @param hashLock    SHA-256 hash of the secret
     * @param timeLock    Unix timestamp after which sender can refund
     * @param token       ERC-20 token address (address(0) for native ETH)
     * @param amount      Amount to lock (ignored for native ETH — uses msg.value)
     * @return id          Unique HTLC identifier
     *
     * selector: 0x4b2f336d
     */
    function createHTLC(
        address recipient,
        bytes32 hashLock,
        uint256 timeLock,
        address token,
        uint256 amount
    ) external payable nonReentrant returns (bytes32 id) {
        require(recipient != address(0), "Invalid recipient");
        require(hashLock != bytes32(0), "Invalid hashLock");
        require(timeLock > block.timestamp, "TimeLock must be in the future");

        htlcCount++;
        id = keccak256(
            abi.encodePacked(msg.sender, recipient, hashLock, htlcCount)
        );

        require(htlcs[id].sender == address(0), "HTLC already exists");

        uint256 lockAmount;

        if (token == address(0)) {
            // Native ETH
            require(msg.value > 0, "Must send ETH");
            lockAmount = msg.value;
        } else {
            // ERC-20
            require(amount > 0, "Amount must be > 0");
            lockAmount = amount;
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        }

        htlcs[id] = HTLC({
            sender: msg.sender,
            recipient: recipient,
            token: token,
            amount: lockAmount,
            hashLock: hashLock,
            timeLock: timeLock,
            status: HTLCStatus.Funded,
            secret: bytes32(0)
        });

        emit HTLCCreated(id, msg.sender, recipient, token, lockAmount, hashLock, timeLock);
    }

    // ─── Claim ──────────────────────────────────────────────

    /**
     * @notice Claim an HTLC by revealing the secret.
     * @param id      HTLC identifier
     * @param secret  Pre-image of the hashLock
     *
     * selector: 0x84cc315c
     */
    function claimHTLC(
        bytes32 id,
        bytes32 secret
    ) external nonReentrant htlcExists(id) {
        HTLC storage h = htlcs[id];

        require(h.status == HTLCStatus.Funded, "HTLC not claimable");
        require(h.recipient == msg.sender, "Not the recipient");
        require(
            sha256(abi.encodePacked(secret)) == h.hashLock,
            "Invalid secret"
        );

        h.status = HTLCStatus.Claimed;
        h.secret = secret;

        if (h.token == address(0)) {
            // Native ETH
            (bool sent, ) = payable(h.recipient).call{value: h.amount}("");
            require(sent, "ETH transfer failed");
        } else {
            // ERC-20
            IERC20(h.token).safeTransfer(h.recipient, h.amount);
        }

        emit HTLCClaimed(id, msg.sender, secret);
    }

    // ─── Refund ─────────────────────────────────────────────

    /**
     * @notice Refund an expired HTLC to the sender.
     * @param id HTLC identifier
     *
     * selector: 0x7249fbb6
     */
    function refundHTLC(
        bytes32 id
    ) external nonReentrant htlcExists(id) {
        HTLC storage h = htlcs[id];

        require(h.status == HTLCStatus.Funded, "HTLC not refundable");
        require(block.timestamp >= h.timeLock, "TimeLock not expired");
        require(h.sender == msg.sender, "Not the sender");

        h.status = HTLCStatus.Refunded;

        if (h.token == address(0)) {
            (bool sent, ) = payable(h.sender).call{value: h.amount}("");
            require(sent, "ETH transfer failed");
        } else {
            IERC20(h.token).safeTransfer(h.sender, h.amount);
        }

        emit HTLCRefunded(id, msg.sender);
    }

    // ─── View ───────────────────────────────────────────────

    /**
     * @notice Get HTLC details.
     * @param id HTLC identifier
     *
     * selector: 0x905d22a5
     */
    function getHTLC(bytes32 id)
        external
        view
        htlcExists(id)
        returns (
            address sender,
            address recipient,
            address token,
            uint256 amount,
            bytes32 hashLock,
            uint256 timeLock,
            HTLCStatus status,
            bytes32 secret
        )
    {
        HTLC storage h = htlcs[id];
        return (
            h.sender,
            h.recipient,
            h.token,
            h.amount,
            h.hashLock,
            h.timeLock,
            h.status,
            h.secret
        );
    }

    /**
     * @notice Check if an HTLC is funded.
     */
    function isHTLCFunded(bytes32 id) external view returns (bool) {
        return htlcs[id].status == HTLCStatus.Funded;
    }

    /**
     * @notice Check if an HTLC has been claimed, and return the secret if so.
     */
    function isHTLCClaimed(bytes32 id) external view returns (bool claimed, bytes32 secret) {
        HTLC storage h = htlcs[id];
        if (h.status == HTLCStatus.Claimed) {
            return (true, h.secret);
        }
        return (false, bytes32(0));
    }

    /**
     * @notice Check if an HTLC timelock has expired.
     */
    function isHTLCExpired(bytes32 id) external view returns (bool) {
        return block.timestamp >= htlcs[id].timeLock && htlcs[id].status == HTLCStatus.Funded;
    }
}

contracts/AtlasSphereX3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract AtlasSphereX3 is ERC20, ERC20Burnable, ERC20Pausable, Ownable {
    address public treasury;
    uint256 public transferFeeBps; // basis points (e.g. 50 = 0.5%)
    uint256 public stakingFeeBps;
    uint256 public swapFeeBps;
    mapping(address => bool) public feeExempt;

    event TreasuryChanged(address indexed newTreasury);
    event FeeUpdated(string feeType, uint256 newBps);
    event FeeExempt(address indexed user, bool exempt);

    constructor(address treasuryAddr) ERC20("Atlas Sphere X3", "X3") {
        require(treasuryAddr != address(0), "ZERO_TREASURY");
        treasury = treasuryAddr;
        transferFeeBps = 50;
        stakingFeeBps = 100;
        swapFeeBps = 25;
        _mint(treasuryAddr, 1_000_000_000 ether);
    }

    function setTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "ZERO_TREASURY");
        treasury = newTreasury;
        emit TreasuryChanged(newTreasury);
    }

    function setFee(string memory feeType, uint256 bps) external onlyOwner {
        if (keccak256(bytes(feeType)) == keccak256("transfer")) transferFeeBps = bps;
        else if (keccak256(bytes(feeType)) == keccak256("staking")) stakingFeeBps = bps;
        else if (keccak256(bytes(feeType)) == keccak256("swap")) swapFeeBps = bps;
        else revert("Invalid fee type");
        emit FeeUpdated(feeType, bps);
    }

    function setFeeExempt(address user, bool exempt) external onlyOwner {
        feeExempt[user] = exempt;
        emit FeeExempt(user, exempt);
    }

    function _transfer(address from, address to, uint256 amount) internal override(ERC20) {
        if (feeExempt[from] || feeExempt[to] || transferFeeBps == 0) {
            super._transfer(from, to, amount);
        } else {
            uint256 fee = (amount * transferFeeBps) / 10000;
            super._transfer(from, treasury, fee);
            super._transfer(from, to, amount - fee);
        }
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal override(ERC20, ERC20Pausable) {
        super._beforeTokenTransfer(from, to, amount);
    }

    function pause() public onlyOwner { _pause(); }
    function unpause() public onlyOwner { _unpause(); }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burnFrom(address account, uint256 amount) public override onlyOwner {
        _burn(account, amount);
    }
}

contracts/EvmReceiptVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./interfaces/IX3Verification.sol";

/// @title EvmReceiptVerifier — production X3 proof verifier for EVM chains
/// @notice Deployed on external EVM chains (e.g. Sepolia testnet) to verify
///         X3 finalized block proofs before the gateway releases funds.
///
/// The verifier maintains a set of authorized X3 validator public keys and
/// requires a supermajority (≥2/3) of them to sign each proof.  The validator
/// set can be rotated atomically by the owner via `rotateValidatorSet()`.
contract EvmReceiptVerifier is IX3Verification, Ownable {
    /// @notice A single X3 validator that signs proofs
    struct Validator {
        /// @notice Ed25519 public key (32 bytes packed)
        bytes32 pubkey;
        /// @notice Whether this validator is currently active
        bool active;
    }

    /// @notice Current verifier set identifier (incremented on rotation)
    uint256 public verifierSetId;

    /// @notice Mapping from validator index to Validator struct
    mapping(uint256 => Validator) public validators;

    /// @notice Number of validators in the current set
    uint256 public validatorCount;

    /// @notice The quorum threshold (must be ≥ 2/3 of validatorCount)
    uint256 public quorumThreshold;

    /// @notice Mapping of verified messageIds to prevent replay
    mapping(bytes32 => bool) public verifiedMessages;

    /// @notice When true, Ed25519 signature verification is skipped and proofs
    /// are accepted based on structure alone (testnet/development mode only).
    bool public testnetMode;

    // ── Events ───────────────────────────────────────────────────────────

    event ValidatorSetRotated(
        uint256 indexed newSetId,
        uint256 validatorCount,
        uint256 quorumThreshold
    );

    event ProofVerified(
        bytes32 indexed messageId,
        uint256 setId,
        uint256 validatorCount,
        uint256 sigCount
    );

    event DepositProofVerified(
        bytes32 indexed messageId,
        address indexed depositor,
        uint256 amount
    );

    event TestnetModeSet(bool enabled);

    // ── Constructor ──────────────────────────────────────────────────────

    /// @param initialValidators Array of Ed25519 validator public keys
    /// @param quorumThreshold_ Minimum signatures required (must be ≥ 2/3 of validators)
    constructor(bytes32[] memory initialValidators, uint256 quorumThreshold_) Ownable() {
        require(initialValidators.length > 0, "Need at least one validator");
        require(
            quorumThreshold_ > 0 && quorumThreshold_ <= initialValidators.length,
            "Invalid quorum threshold"
        );

        verifierSetId = 1;
        validatorCount = initialValidators.length;
        quorumThreshold = quorumThreshold_;

        for (uint256 i = 0; i < initialValidators.length; i++) {
            validators[i] = Validator({pubkey: initialValidators[i], active: true});
        }

        emit ValidatorSetRotated(verifierSetId, validatorCount, quorumThreshold);
    }

    // ── IX3Verification implementation ───────────────────────────────────

    /// @inheritdoc IX3Verification
    function verifyX3WithdrawalProof(
        bytes32 messageId,
        uint256 sourceChain,
        bytes calldata sender,
        address recipient,
        uint256 amount,
        bytes calldata proof
    ) external view override returns (bool verified) {
        // Replay protection: already-verified messages cannot be replayed
        if (verifiedMessages[messageId]) {
            return false;
        }

        // Decode proof: first 4 bytes = verifierSetId (big-endian),
        // optionally followed by N × (32-byte pubkey-index || 64-byte signature)
        // For testnet phase: accept proof that consists of at least
        // quorumThreshold valid Ed25519 signatures from active validators.
        bytes32 proofMessage = keccak256(
            abi.encodePacked(messageId, sourceChain, sender, recipient, amount)
        );

        uint256 sigCount = _countValidSignatures(proofMessage, proof);
        return sigCount >= quorumThreshold;
    }

    /// @inheritdoc IX3Verification
    function verifyDepositProof(
        bytes32 messageId,
        address token,
        address depositor,
        bytes calldata x3Recipient,
        uint256 amount,
        bytes calldata proof
    ) external view override returns (bool verified) {
        // Replay protection
        if (verifiedMessages[messageId]) {
            return false;
        }

        // Deposit proof: the gateway emits an event when tokens are locked.
        // For testnet phase, verify that the proof contains a valid
        // Ed25519 signature from the quorum set over the deposit payload.
        bytes32 proofMessage = keccak256(
            abi.encodePacked(messageId, token, depositor, x3Recipient, amount)
        );

        uint256 sigCount = _countValidSignatures(proofMessage, proof);
        return sigCount >= quorumThreshold;
    }

    // ── Admin functions ──────────────────────────────────────────────────

    /// @notice Rotate the validator set atomically.
    /// @param newValidators New array of Ed25519 public keys
    /// @param newQuorumThreshold New quorum threshold
    function rotateValidatorSet(
        bytes32[] calldata newValidators,
        uint256 newQuorumThreshold
    ) external onlyOwner {
        require(newValidators.length > 0, "Need at least one validator");
        require(
            newQuorumThreshold > 0 && newQuorumThreshold <= newValidators.length,
            "Invalid quorum threshold"
        );

        verifierSetId += 1;
        validatorCount = newValidators.length;
        quorumThreshold = newQuorumThreshold;

        for (uint256 i = 0; i < newValidators.length; i++) {
            validators[i] = Validator({pubkey: newValidators[i], active: true});
        }
        // Clear stale entries beyond the new count
        for (uint256 i = newValidators.length; i < newValidators.length + 64; i++) {
            if (validators[i].active) {
                validators[i].active = false;
            } else {
                break;
            }
        }

        emit ValidatorSetRotated(verifierSetId, validatorCount, quorumThreshold);
    }

    /// @notice Mark a message as verified (called by gateway after token release).
    /// Only the owner (or the gateway itself via a separate access list) may call.
    function markVerified(bytes32 messageId) external onlyOwner {
        verifiedMessages[messageId] = true;
    }

    /// @notice Enable or disable testnet mode. When enabled, Ed25519 signature
    /// verification is skipped and proofs are accepted based on structure alone.
    /// @param enabled True to enable testnet mode, false to disable.
    function setTestnetMode(bool enabled) external onlyOwner {
        testnetMode = enabled;
        emit TestnetModeSet(enabled);
    }

    // ── Internal helpers ─────────────────────────────────────────────────

    /// @dev Count valid Ed25519 signatures in the proof blob.
    ///
    /// Proof format (testnet v1):
    ///   [4 bytes] verifierSetId (big-endian uint32)
    ///   [N × (1 byte index || 64 bytes signature)]
    ///
    /// In production mode (testnetMode == false): reverts unconditionally
    /// because on-chain Ed25519 verification is not available on EVM
    /// (EIP-665 is not finalized). This prevents forged proofs from
    /// releasing bridge funds.
    ///
    /// In testnet mode: parses the proof structure and returns the number
    /// of signature slots without verifying the actual Ed25519 signatures.
    /// The proof must have a valid verifierSetId and correct structure,
    /// but individual signatures are not cryptographically verified.
    function _countValidSignatures(
        bytes32 message,
        bytes memory proof
    ) internal view returns (uint256 count) {
        if (!testnetMode) {
            revert("EvmReceiptVerifier: on-chain Ed25519 verification not available - bridge blocked");
        }

        require(proof.length >= 4, "Proof too short");

        uint32 setId = _bytesToUint32(proof, 0);
        require(setId == verifierSetId, "VerifierSetId mismatch");

        uint256 sigBytes = proof.length - 4;
        require(sigBytes % 65 == 0, "Invalid signature data length");

        for (uint256 i = 0; i < sigBytes; i += 65) {
            if (proof[4 + i] != 0) {
                count++;
            }
        }
    }

    /// @dev Read a big-endian uint32 from bytes at `start`
    function _bytesToUint32(bytes memory b, uint256 start) internal pure returns (uint32 result) {
        require(start + 4 <= b.length, "OOB");
        assembly {
            result := shr(224, mload(add(add(b, 0x20), start)))
        }
    }
}

contracts/WrappedX3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface IUniversalAdapter {
    function verifyDeposit(address user, uint256 amount, uint256 chainId) external returns (bool);
    function verifyWithdraw(address user, uint256 amount, uint256 chainId) external returns (bool);
}

contract WrappedX3 is ERC20, Ownable {
    address public treasury;
    address public adapter;
    uint256 public treasuryFeeBps;
    uint256 public immutable chainId;
    mapping(address => bool) public feeExempt;

    event TreasuryChanged(address indexed newTreasury);
    event AdapterChanged(address indexed newAdapter);
    event FeeUpdated(uint256 newBps);
    event FeeExempt(address indexed user, bool exempt);

    constructor(address treasuryAddr, address adapterAddr, uint256 chainId_) ERC20("Wrapped X3", "wX3") {
        require(treasuryAddr != address(0), "ZERO_TREASURY");
        require(adapterAddr != address(0), "ZERO_ADAPTER");
        treasury = treasuryAddr;
        adapter = adapterAddr;
        chainId = chainId_;
        treasuryFeeBps = 50;
    }

    function setTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "ZERO_TREASURY");
        treasury = newTreasury;
        emit TreasuryChanged(newTreasury);
    }

    function setAdapter(address newAdapter) external onlyOwner {
        require(newAdapter != address(0), "ZERO_ADAPTER");
        adapter = newAdapter;
        emit AdapterChanged(newAdapter);
    }

    function setFee(uint256 bps) external onlyOwner {
        treasuryFeeBps = bps;
        emit FeeUpdated(bps);
    }

    function setFeeExempt(address user, bool exempt) external onlyOwner {
        feeExempt[user] = exempt;
        emit FeeExempt(user, exempt);
    }

    event Mint(address indexed to, uint256 amount, uint256 fee);
    event Burn(address indexed from, uint256 amount);

    function mint(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "ZERO_TO");
        require(amount > 0, "ZERO_AMOUNT");
        uint256 fee = feeExempt[to] ? 0 : (amount * treasuryFeeBps) / 10000;
        if (fee > 0) _mint(treasury, fee);
        _mint(to, amount - fee);
        emit Mint(to, amount, fee);
    }

    function burn(address from, uint256 amount) external onlyOwner {
        require(from != address(0), "ZERO_FROM");
        require(amount > 0, "ZERO_AMOUNT");
        _burn(from, amount);
        emit Burn(from, amount);
    }
}

contracts/X3ExternalGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./interfaces/IX3Verification.sol";

/// @title X3ExternalGateway — External chain lock/release gateway for X3
/// @notice Deployed once per external EVM chain (Ethereum, Base, Arbitrum, etc.)
/// @dev Users deposit ERC20 tokens here → relayers submit proofs to X3 → X3 mints wrapped
///      X3 burns wrapped → relayers submit proofs here → tokens released
contract X3ExternalGateway is Ownable {
    using SafeERC20 for IERC20;

    /// @notice Proof verifier contract (handles X3 finalized proof verification)
    IX3Verification public verifier;

    /// @notice Supported tokens that can be deposited into X3
    mapping(address => bool) public supportedTokens;

    /// @notice Per-token daily deposit limits (in token decimals)
    mapping(address => uint256) public dailyDepositLimits;

    /// @notice Per-token daily withdrawal limits
    mapping(address => uint256) public dailyWithdrawalLimits;

    /// @notice Rolling window accumulators (resets daily)
    /// token => dayTimestamp => totalDeposited
    mapping(address => mapping(uint256 => uint256)) public dailyDeposited;

    /// @notice token => dayTimestamp => totalWithdrawn
    mapping(address => mapping(uint256 => uint256)) public dailyWithdrawn;

    /// @notice Replay protection — used message IDs
    mapping(bytes32 => bool) public usedMessages;

    /// @notice Total value locked per token
    mapping(address => uint256) public totalLocked;

    /// @notice Emergency pause
    bool public paused;

    /// @notice Chain ID of this gateway (Ethereum=1, Base=8453, Arbitrum=42161, etc.)
    uint256 public immutable chainId;

    /// @notice X3 destination chain ID
    uint256 public immutable x3ChainId;

    /// @notice Minimum confirmations required for X3 finality proof
    uint256 public minX3Confirmations;

    // ── Events ──────────────────────────────────────────────────────────────

    /// @notice Emitted when a user deposits tokens to bridge to X3
    event DepositLocked(
        bytes32 indexed messageId,
        address indexed token,
        address indexed depositor,
        bytes x3Recipient,
        uint256 amount,
        uint256 nonce,
        uint256 chainId
    );

    /// @notice Emitted when tokens are released to a recipient after X3 proof
    event WithdrawalReleased(
        bytes32 indexed messageId,
        address indexed token,
        address indexed recipient,
        uint256 amount
    );

    /// @notice Emitted when gateway is paused or unpaused
    event Paused(bool isPaused);

    /// @notice Emitted when a token is added or removed from supported list
    event SupportedTokenUpdated(address indexed token, bool supported, uint256 dailyDepositCap, uint256 dailyWithdrawalCap);

    /// @notice Emitted when verifier contract is updated
    event VerifierUpdated(address indexed newVerifier);

    // ── Constructor ─────────────────────────────────────────────────────────

    constructor(
        address _verifier,
        uint256 _chainId,
        uint256 _x3ChainId,
        uint256 _minX3Confirmations
    ) {
        require(_verifier != address(0), "ZERO_VERIFIER");
        verifier = IX3Verification(_verifier);
        chainId = _chainId;
        x3ChainId = _x3ChainId;
        minX3Confirmations = _minX3Confirmations;
    }

    // ── Modifiers ───────────────────────────────────────────────────────────

    modifier whenNotPaused() {
        require(!paused, "GATEWAY_PAUSED");
        _;
    }

    modifier onlySupportedToken(address token) {
        require(supportedTokens[token], "TOKEN_NOT_SUPPORTED");
        _;
    }

    // ── Admin Functions ─────────────────────────────────────────────────────

    /// @notice Set or update a supported token with daily limits
    function setSupportedToken(
        address token,
        bool supported,
        uint256 dailyDepositCap,
        uint256 dailyWithdrawalCap
    ) external onlyOwner {
        supportedTokens[token] = supported;
        dailyDepositLimits[token] = dailyDepositCap;
        dailyWithdrawalLimits[token] = dailyWithdrawalCap;
        emit SupportedTokenUpdated(token, supported, dailyDepositCap, dailyWithdrawalCap);
    }

    /// @notice Update the verifier contract address
    function setVerifier(address newVerifier) external onlyOwner {
        require(newVerifier != address(0), "ZERO_VERIFIER");
        verifier = IX3Verification(newVerifier);
        emit VerifierUpdated(newVerifier);
    }

    /// @notice Emergency pause/unpause
    function setPaused(bool paused_) external onlyOwner {
        paused = paused_;
        emit Paused(paused_);
    }

    /// @notice Set minimum X3 confirmations for proof acceptance
    function setMinX3Confirmations(uint256 min_) external onlyOwner {
        minX3Confirmations = min_;
    }

    // ── Core Functions ──────────────────────────────────────────────────────

    /// @notice Deposit ERC20 tokens into the gateway to mint on X3
    /// @param token The ERC20 token address
    /// @param x3Recipient The recipient address on X3 (SCALE-encoded)
    /// @param amount The amount of tokens to deposit
    /// @param nonce User-provided nonce for replay protection
    function depositToX3(
        address token,
        bytes calldata x3Recipient,
        uint256 amount,
        uint256 nonce
    ) external whenNotPaused onlySupportedToken(token) {
        require(amount > 0, "ZERO_AMOUNT");
        require(x3Recipient.length > 0 && x3Recipient.length <= 64, "INVALID_RECIPIENT");

        bytes32 messageId = keccak256(
            abi.encodePacked(
                "X3_DEPOSIT_V1",
                chainId,
                token,
                msg.sender,
                x3Recipient,
                amount,
                nonce
            )
        );

        require(!usedMessages[messageId], "REPLAY");
        usedMessages[messageId] = true;

        // Enforce daily deposit limit
        uint256 dayKey = block.timestamp / 86400;
        uint256 dayDeposited = dailyDeposited[token][dayKey];
        uint256 newDayDeposited = dayDeposited + amount;
        require(newDayDeposited <= dailyDepositLimits[token], "DAILY_DEPOSIT_LIMIT");
        dailyDeposited[token][dayKey] = newDayDeposited;

        // Transfer tokens from user to this contract
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        totalLocked[token] += amount;

        emit DepositLocked(
            messageId,
            token,
            msg.sender,
            x3Recipient,
            amount,
            nonce,
            chainId
        );
    }

    /// @notice Release tokens to recipient after verified X3 withdrawal proof
    /// @param messageId The X3 withdrawal message ID
    /// @param token The ERC20 token address to release
    /// @param recipient The recipient address on this chain
    /// @param amount The amount to release
    /// @param sender The sender on X3 side (SCALE-encoded)
    /// @param proof The X3 finalized proof data
    function releaseFromX3(
        bytes32 messageId,
        address token,
        address recipient,
        uint256 amount,
        bytes calldata sender,
        bytes calldata proof
    ) external whenNotPaused onlySupportedToken(token) {
        require(!usedMessages[messageId], "REPLAY");
        require(recipient != address(0), "ZERO_RECIPIENT");
        require(amount > 0, "ZERO_AMOUNT");
        require(totalLocked[token] >= amount, "INSUFFICIENT_LIQUIDITY");

        // Verify X3 withdrawal proof
        bool verified = verifier.verifyX3WithdrawalProof(
            messageId,
            x3ChainId,
            sender,
            recipient,
            amount,
            proof
        );
        require(verified, "INVALID_X3_PROOF");

        usedMessages[messageId] = true;

        // Enforce daily withdrawal limit
        uint256 dayKey = block.timestamp / 86400;
        uint256 dayWithdrawn = dailyWithdrawn[token][dayKey];
        uint256 newDayWithdrawn = dayWithdrawn + amount;
        require(newDayWithdrawn <= dailyWithdrawalLimits[token], "DAILY_WITHDRAWAL_LIMIT");
        dailyWithdrawn[token][dayKey] = newDayWithdrawn;

        // Release tokens
        totalLocked[token] -= amount;
        IERC20(token).safeTransfer(recipient, amount);

        emit WithdrawalReleased(messageId, token, recipient, amount);
    }

    /// @notice Get daily remaining capacity for a token
    function getRemainingDailyDeposit(address token) external view returns (uint256) {
        uint256 dayKey = block.timestamp / 86400;
        uint256 deposited = dailyDeposited[token][dayKey];
        uint256 limit = dailyDepositLimits[token];
        if (deposited >= limit) return 0;
        return limit - deposited;
    }

    /// @notice Get daily remaining withdrawal capacity for a token
    function getRemainingDailyWithdrawal(address token) external view returns (uint256) {
        uint256 dayKey = block.timestamp / 86400;
        uint256 withdrawn = dailyWithdrawn[token][dayKey];
        uint256 limit = dailyWithdrawalLimits[token];
        if (withdrawn >= limit) return 0;
        return limit - withdrawn;
    }
}

contracts/X3KernelBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";

/// @title X3KernelBridge — Bridge interface between X3 runtime and EVM contracts
/// @notice Deployed on X3 EVM side, called by the X3 runtime pallet
/// @dev This is the contract that the X3 kernel calls to trigger EVM-side operations
contract X3KernelBridge is AccessControl {
    bytes32 public constant KERNEL_ROLE = keccak256("KERNEL_ROLE");

    /// @notice Registered token adapters: assetId => X3VmERC20 address
    mapping(bytes32 => address) public tokenAdapters;

    /// @notice Registered external gateways: chainId => gateway address
    mapping(uint256 => address) public externalGateways;

    /// @notice Emitted when a token adapter is registered
    event TokenAdapterRegistered(bytes32 indexed assetId, address indexed adapter);

    /// @notice Emitted when an external gateway is registered
    event ExternalGatewayRegistered(uint256 indexed chainId, address indexed gateway);

    /// @notice Emitted when a cross-VM transfer is completed (destination credited)
    event CrossVmTransferCompleted(
        bytes32 indexed messageId,
        bytes32 indexed assetId,
        address indexed recipient,
        uint256 amount
    );

    /// @notice Emitted when an external deposit is completed
    event ExternalDepositCompleted(
        bytes32 indexed messageId,
        bytes32 indexed assetId,
        address indexed recipient,
        uint256 amount,
        uint256 sourceChainId
    );

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(KERNEL_ROLE, msg.sender);
    }

    /// @notice Register a token adapter for a canonical asset
    function registerTokenAdapter(bytes32 assetId, address adapter) external onlyRole(KERNEL_ROLE) {
        require(adapter != address(0), "ZERO_ADAPTER");
        require(tokenAdapters[assetId] == address(0), "ALREADY_REGISTERED");
        tokenAdapters[assetId] = adapter;
        emit TokenAdapterRegistered(assetId, adapter);
    }

    /// @notice Register an external gateway for a chain
    function registerExternalGateway(uint256 chainId, address gateway) external onlyRole(KERNEL_ROLE) {
        require(gateway != address(0), "ZERO_GATEWAY");
        externalGateways[chainId] = gateway;
        emit ExternalGatewayRegistered(chainId, gateway);
    }

    /// @notice Mint tokens to a user on EVM (called by kernel for cross-VM or cross-chain credit)
    function creditUser(
        bytes32 messageId,
        bytes32 assetId,
        address recipient,
        uint256 amount
    ) external onlyRole(KERNEL_ROLE) returns (bool) {
        address adapter = tokenAdapters[assetId];
        require(adapter != address(0), "NO_ADAPTER");
        require(recipient != address(0), "ZERO_RECIPIENT");
        require(amount > 0, "ZERO_AMOUNT");

        // Call the adapter to mint
        (bool success, ) = adapter.call(
            abi.encodeWithSignature("kernelMint(address,uint256)", recipient, amount)
        );
        require(success, "MINT_FAILED");

        emit CrossVmTransferCompleted(messageId, assetId, recipient, amount);
        return true;
    }

    /// @notice Burn tokens from a user on EVM (called by kernel for cross-VM or cross-chain debit)
    function debitUser(
        bytes32 messageId,
        bytes32 assetId,
        address user,
        uint256 amount
    ) external onlyRole(KERNEL_ROLE) returns (bool) {
        address adapter = tokenAdapters[assetId];
        require(adapter != address(0), "NO_ADAPTER");
        require(user != address(0), "ZERO_USER");
        require(amount > 0, "ZERO_AMOUNT");

        // Call the adapter to burn
        (bool success, ) = adapter.call(
            abi.encodeWithSignature("kernelBurn(address,uint256)", user, amount)
        );
        require(success, "BURN_FAILED");

        return true;
    }

    /// @notice Get the adapter address for a given asset
    function getAdapter(bytes32 assetId) external view returns (address) {
        return tokenAdapters[assetId];
    }

    /// @notice Get the gateway address for a given chain
    function getGateway(uint256 chainId) external view returns (address) {
        return externalGateways[chainId];
    }
}

contracts/X3VmERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/// @title X3VmERC20 — Kernel-callable ERC20 adapter for X3 cross-VM and cross-chain
/// @notice This contract is the EVM-side representation of any X3-registered asset.
/// @dev Only the X3 kernel address can mint/burn. This ensures supply parity
///      with the canonical X3 supply ledger.
contract X3VmERC20 is ERC20, AccessControl {
    bytes32 public constant KERNEL_ROLE = keccak256("KERNEL_ROLE");
    bytes32 public constant BRIDGE_ROLE = keccak256("BRIDGE_ROLE");

    /// @notice The canonical X3 asset ID (32 bytes, H256 format)
    bytes32 public immutable assetId;

    /// @notice The origin domain this ERC20 represents (X3Native, X3Svm, Ethereum, etc.)
    uint8 public immutable originDomain;

    /// @notice The original chain ID (for external assets)
    uint256 public immutable originChainId;

    /// @notice The original token address on its native chain (zero for X3-native)
    address public immutable originToken;

    /// @notice Decimals for this token
    uint8 private immutable _decimals;

    // ── Events ──────────────────────────────────────────────────────────────

    /// @notice Emitted when tokens are sent to another VM via the kernel
    event CrossVmTransferInitiated(
        bytes32 indexed assetId,
        address indexed sender,
        uint8 destinationDomain,
        bytes recipient,
        uint256 amount
    );

    /// @notice Emitted when tokens are minted by the kernel
    event KernelMint(
        bytes32 indexed assetId,
        address indexed to,
        uint256 amount
    );

    /// @notice Emitted when tokens are burned by the kernel
    event KernelBurn(
        bytes32 indexed assetId,
        address indexed from,
        uint256 amount
    );

    // ── Constructor ─────────────────────────────────────────────────────────

    constructor(
        string memory name_,
        string memory symbol_,
        uint8 _tokenDecimals,
        bytes32 _assetId,
        uint8 _originDomain,
        uint256 _originChainId,
        address originToken_,
        address _kernel
    ) ERC20(name_, symbol_) {
        require(_kernel != address(0), "ZERO_KERNEL");
        assetId = _assetId;
        originDomain = _originDomain;
        originChainId = _originChainId;
        // slither-disable-next-line missing-zero-check
        // address(0) is valid - represents native chain tokens
        originToken = originToken_;
        _decimals = _tokenDecimals;

        _grantRole(DEFAULT_ADMIN_ROLE, _kernel);
        _grantRole(KERNEL_ROLE, _kernel);
    }

    // ── Overrides ──────────────────────────────────────────────────────────

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    // ── Kernel Functions ────────────────────────────────────────────────────

    /// @notice Mint tokens via kernel authority (cross-chain deposit or cross-VM mint)
    /// @param to The recipient address
    /// @param amount The amount to mint
    function kernelMint(address to, uint256 amount) external onlyRole(KERNEL_ROLE) {
        require(to != address(0), "ZERO_TO");
        require(amount > 0, "ZERO_AMOUNT");
        _mint(to, amount);
        emit KernelMint(assetId, to, amount);
    }

    /// @notice Burn tokens via kernel authority (cross-chain withdrawal or cross-VM burn)
    /// @param from The address to burn from
    /// @param amount The amount to burn
    function kernelBurn(address from, uint256 amount) external onlyRole(KERNEL_ROLE) {
        require(from != address(0), "ZERO_FROM");
        require(amount > 0, "ZERO_AMOUNT");
        _burn(from, amount);
        emit KernelBurn(assetId, from, amount);
    }

    /// @notice Initiate a cross-VM transfer through the kernel
    /// @param destinationDomain The target VM domain ID
    /// @param recipient The recipient on the destination VM (domain-encoded)
    /// @param amount The amount to transfer
    function sendToVm(
        uint8 destinationDomain,
        bytes calldata recipient,
        uint256 amount
    ) external {
        require(balanceOf(msg.sender) >= amount, "INSUFFICIENT_BALANCE");
        require(recipient.length > 0 && recipient.length <= 64, "INVALID_RECIPIENT");

        // Burn local representation — the cross-VM router will mint on destination
        _burn(msg.sender, amount);
        emit Transfer(msg.sender, address(0), amount);

        emit CrossVmTransferInitiated(
            assetId,
            msg.sender,
            destinationDomain,
            recipient,
            amount
        );
    }

    // ── Bridge Role Functions ──────────────────────────────────────────────

    /// @notice Mint tokens via bridge authority (for external chain deposits)
    /// @param to The recipient address
    /// @param amount The amount to mint
    function bridgeMint(address to, uint256 amount) external onlyRole(BRIDGE_ROLE) {
        require(to != address(0), "ZERO_TO");
        require(amount > 0, "ZERO_AMOUNT");
        _mint(to, amount);
        emit KernelMint(assetId, to, amount);
    }

    /// @notice Burn tokens via bridge authority (for external chain withdrawals)
    /// @param from The address to burn from
    /// @param amount The amount to burn
    function bridgeBurn(address from, uint256 amount) external onlyRole(BRIDGE_ROLE) {
        require(from != address(0), "ZERO_FROM");
        require(amount > 0, "ZERO_AMOUNT");
        _burn(from, amount);
        emit KernelBurn(assetId, from, amount);
    }

    /// @notice Grant bridge role to the external gateway contract
    function grantBridgeRole(address gateway) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(BRIDGE_ROLE, gateway);
    }

    /// @notice Revoke bridge role
    function revokeBridgeRole(address gateway) external onlyRole(DEFAULT_ADMIN_ROLE) {
        revokeRole(BRIDGE_ROLE, gateway);
    }
}

contracts/flashloan/X3Flashloan.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import {IX3FlashloanReceiver} from "../interfaces/IX3FlashloanReceiver.sol";

/// @notice Minimal ERC20 surface used by the flashloan core. Kept inline to
///         avoid pulling a full token library into a launch-critical contract.
interface IERC20Like {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @title X3Flashloan
/// @notice Repay-or-revert flashloan core. Mirrors the SVM `x3_core::flashloan`
///         program. The behavior contract is defined by
///         `X3-contracts/shared/test-vectors/flashloan_repay_or_revert.json`.
///
/// Invariants enforced here:
///   I1 (atomicity)     : terminal balance must be >= pre-balance + fee, else revert.
///   I2 (no reentrancy) : a flashloan call cannot recursively borrow the same asset.
///   I3 (fee monotonic) : `fee` is purely additive; the protocol never owes the borrower.
contract X3Flashloan {
    /// @dev Returned by `IX3FlashloanReceiver.onFlashloan` on success.
    bytes32 public constant CALLBACK_OK = keccak256("X3Flashloan.onFlashloan.OK");

    /// @dev Fee is in basis points of `amount`. 9 bps == 0.09%.
    uint256 public immutable feeBps;

    /// @dev Reentrancy lock keyed per asset.
    mapping(address => bool) private _locked;

    error AlreadyEntered(address asset);
    error CallbackFailed();
    error NotRepaid(uint256 expected, uint256 got);
    error TransferFailed();

    event Flashloan(
        address indexed asset,
        address indexed borrower,
        uint256 amount,
        uint256 fee
    );

    constructor(uint256 _feeBps) {
        // Cap at 1000 bps (10%) defensively; X3 default is 9 bps.
        require(_feeBps <= 1000, "fee too high");
        feeBps = _feeBps;
    }

    /// @notice Compute the fee for a flashloan amount. Rounds up so the
    ///         protocol cannot be drained by repeated 1-wei loans.
    function quoteFee(uint256 amount) public view returns (uint256) {
        uint256 num = amount * feeBps;
        return (num + 9_999) / 10_000;
    }

    /// @notice Atomically lend `amount` of `asset` to `borrower`, invoke its
    ///         `onFlashloan` hook, and require repayment in the same call.
    function flashloan(
        address asset,
        uint256 amount,
        address borrower,
        bytes calldata data
    ) external {
        if (_locked[asset]) revert AlreadyEntered(asset);
        _locked[asset] = true;

        IERC20Like token = IERC20Like(asset);
        uint256 fee = quoteFee(amount);
        uint256 preBalance = token.balanceOf(address(this));

        // Lend.
        if (!token.transfer(borrower, amount)) revert TransferFailed();

        // Borrower must return amount + fee before this call returns.
        bytes32 ack = IX3FlashloanReceiver(borrower).onFlashloan(
            asset,
            amount,
            fee,
            data
        );
        if (ack != CALLBACK_OK) revert CallbackFailed();

        uint256 postBalance = token.balanceOf(address(this));
        uint256 minRepayment = preBalance + fee;
        if (postBalance < minRepayment) revert NotRepaid(minRepayment, postBalance);

        emit Flashloan(asset, borrower, amount, fee);

        _locked[asset] = false;
    }
}

contracts/foundry/FoundryAppFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Create2.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryAppFactory — dApp Factory for X3 Foundry
/// @notice Factory contract that deploys new dApp contracts from templates using CREATE2
/// @dev Uses deterministic addresses via CREATE2 for predictable deployments
contract FoundryAppFactory is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Represents a deployed dApp instance
    struct DeployedApp {
        uint256 appId;
        address appAddress;
        address deployer;
        uint256 templateId;
        bytes initData;
        uint256 deployedAt;
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Incremental app ID counter
    uint256 private _appCount;

    /// @notice App ID => DeployedApp
    mapping(uint256 => DeployedApp) private _deployedApps;

    /// @notice Deployer address => array of deployed app IDs
    mapping(address => uint256[]) private _deployerApps;

    /// @notice App address => app ID
    mapping(address => uint256) private _appIdByAddress;

    /// @notice Template registry address (for template lookups)
    address public templateRegistry;

    /// @notice Default salt nonce for CREATE2
    uint256 private _saltNonce;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a new dApp is created
    event AppCreated(
        uint256 indexed appId,
        address indexed appAddress,
        address indexed deployer,
        uint256 templateId,
        bytes initData,
        uint256 timestamp
    );

    /// @notice Emitted when the template registry is updated
    event TemplateRegistryUpdated(address indexed newRegistry, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyInitData();
    error DeploymentFailed();
    error AppAlreadyExists(address appAddress);
    error InvalidTemplate();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(address registry) {
        _transferOwnership(msg.sender);
        if (registry == address(0)) revert ZeroAddress();
        templateRegistry = registry;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Update the template registry address
    /// @param registry New template registry address
    function setTemplateRegistry(address registry) external onlyOwner {
        if (registry == address(0)) revert ZeroAddress();
        templateRegistry = registry;
        emit TemplateRegistryUpdated(registry, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Create a new dApp by deploying contract bytecode directly
    /// @param initCode The full init code (creation code + constructor args) of the dApp
    /// @param salt Optional salt for CREATE2 (use bytes32(0) for auto-generated)
    /// @return appAddress The address of the deployed dApp
    function createApp(bytes calldata initCode, bytes32 salt) external nonReentrant returns (address appAddress) {
        if (initCode.length == 0) revert EmptyInitData();

        // Generate deterministic salt if not provided
        if (salt == bytes32(0)) {
            _saltNonce++;
            salt = keccak256(abi.encodePacked(msg.sender, _saltNonce, block.timestamp));
        }

        // Deploy using CREATE2
        appAddress = Create2.deploy(0, salt, initCode);

        if (appAddress == address(0)) revert DeploymentFailed();
        if (_appIdByAddress[appAddress] != 0) revert AppAlreadyExists(appAddress);

        _registerApp(appAddress, msg.sender, 0, initCode);
    }

    /// @notice Create a new dApp from a registered template
    /// @param templateId The template ID to use
    /// @param initData The initialization data (constructor arguments / initializer params)
    /// @param salt Optional salt for CREATE2 (use bytes32(0) for auto-generated)
    /// @return appAddress The address of the deployed dApp
    function createAppFromTemplate(
        uint256 templateId,
        bytes calldata initData,
        bytes32 salt
    ) external nonReentrant returns (address appAddress) {
        if (templateId == 0) revert InvalidTemplate();

        // In a full implementation, we would fetch the template's bytecode from the registry
        // and concatenate it with initData. For this factory, we expect the caller to provide
        // the full init code or use a proxy pattern.
        // Here we deploy a minimal proxy (EIP-1167) pointing to the template implementation.

        // For simplicity, we use a minimal proxy pattern:
        // The template registry stores a templateAddress which is the implementation.
        // We deploy a clone using CREATE2.

        // This is a placeholder for the actual template bytecode retrieval.
        // In production, the template registry would store the bytecode or implementation address.
        // We emit the event and register the app.

        // Generate deterministic salt if not provided
        if (salt == bytes32(0)) {
            _saltNonce++;
            salt = keccak256(abi.encodePacked(msg.sender, _saltNonce, block.timestamp, templateId));
        }

        // Deploy a minimal proxy (EIP-1167) to the template implementation
        // The template address is fetched from the registry
        // For this implementation, we use a generic minimal proxy deployment

        // NOTE: In a real deployment, you'd call ITemplateRegistry(templateRegistry).getTemplate(templateId)
        // and use the templateAddress field. Here we deploy a generic minimal proxy.

        // Minimal proxy bytecode: 3d602d80600a3d3981f3363d3d373d3d3d363d73...address...5af43d82803e903d91602b57fd5bf3
        // For now, we deploy a simple contract using the initData as the full init code
        if (initData.length == 0) revert EmptyInitData();

        appAddress = Create2.deploy(0, salt, initData);

        if (appAddress == address(0)) revert DeploymentFailed();
        if (_appIdByAddress[appAddress] != 0) revert AppAlreadyExists(appAddress);

        _registerApp(appAddress, msg.sender, templateId, initData);
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Register a deployed app in the factory's state
    function _registerApp(
        address appAddress,
        address deployer,
        uint256 templateId,
        bytes memory initData
    ) internal {
        _appCount++;
        uint256 appId = _appCount;

        _deployedApps[appId] = DeployedApp({
            appId: appId,
            appAddress: appAddress,
            deployer: deployer,
            templateId: templateId,
            initData: initData,
            deployedAt: block.timestamp
        });

        _deployerApps[deployer].push(appId);
        _appIdByAddress[appAddress] = appId;

        emit AppCreated(appId, appAddress, deployer, templateId, initData, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get total number of deployed apps
    /// @return count The app count
    function getDeployedAppCount() external view returns (uint256) {
        return _appCount;
    }

    /// @notice Get deployed app info by ID
    /// @param appId The app ID
    /// @return DeployedApp struct
    function getDeployedApp(uint256 appId) external view returns (DeployedApp memory) {
        return _deployedApps[appId];
    }

    /// @notice Get all deployed apps (paginated)
    /// @param offset Starting index (0-based)
    /// @param limit Maximum number of results
    /// @return apps Array of DeployedApp
    function getDeployedApps(uint256 offset, uint256 limit) external view returns (DeployedApp[] memory apps) {
        if (offset >= _appCount) return new DeployedApp[](0);
        uint256 end = offset + limit;
        if (end > _appCount) end = _appCount;
        uint256 resultCount = end - offset;
        apps = new DeployedApp[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            apps[i] = _deployedApps[offset + i + 1];
        }
    }

    /// @notice Get all apps deployed by a specific deployer
    /// @param deployer The deployer address
    /// @return apps Array of DeployedApp
    function getDeployerApps(address deployer) external view returns (DeployedApp[] memory apps) {
        uint256[] storage appIds = _deployerApps[deployer];
        uint256 len = appIds.length;
        apps = new DeployedApp[](len);
        for (uint256 i = 0; i < len; i++) {
            apps[i] = _deployedApps[appIds[i]];
        }
    }

    /// @notice Get app ID by deployed address
    /// @param appAddress The deployed dApp address
    /// @return appId The app ID (0 if not found)
    function getAppIdByAddress(address appAddress) external view returns (uint256) {
        return _appIdByAddress[appAddress];
    }

    /// @notice Predict the address of a CREATE2 deployment
    /// @param initCodeHash keccak256 of the init code
    /// @param salt The salt
    /// @return predictedAddress The predicted address
    function predictAppAddress(bytes32 initCodeHash, bytes32 salt) external view returns (address) {
        return Create2.computeAddress(salt, initCodeHash);
    }

    /// @notice Predict the address of a CREATE2 deployment with a specific deployer
    /// @param initCodeHash keccak256 of the init code
    /// @param salt The salt
    /// @param deployer The deployer address
    /// @return predictedAddress The predicted address
    function predictAppAddressByDeployer(
        bytes32 initCodeHash,
        bytes32 salt,
        address deployer
    ) external view returns (address) {
        return Create2.computeAddress(salt, initCodeHash, deployer);
    }
}

contracts/foundry/FoundryCreatorVault.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title FoundryCreatorVault — Creator Revenue Vault for X3 Foundry
/// @notice Vault for creator revenue using pull-over-push pattern
/// @dev Uses ReentrancyGuard for safety and Ownable for admin functions
contract FoundryCreatorVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Represents a creator's balance snapshot
    struct CreatorBalance {
        uint256 nativeBalance;      // Balance in native currency (wei)
        uint256 totalDeposited;     // Total native deposited all-time
        uint256 totalWithdrawn;     // Total native withdrawn all-time
        uint256 lastClaimTime;      // Timestamp of last withdrawal
    }

    /// @notice Represents a creator's ERC20 token balance
    struct TokenBalance {
        uint256 balance;
        uint256 totalDeposited;
        uint256 totalWithdrawn;
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Creator address => CreatorBalance (native)
    mapping(address => CreatorBalance) private _nativeBalances;

    /// @notice Creator address => token address => TokenBalance
    mapping(address => mapping(address => TokenBalance)) private _tokenBalances;

    /// @notice Total native currency distributed all-time
    uint256 public totalNativeDistributed;

    /// @notice Total native currency withdrawn all-time
    uint256 public totalNativeWithdrawn;

    /// @notice Set of creators who have balances
    address[] private _creators;

    /// @notice Whether a creator is tracked
    mapping(address => bool) private _isCreator;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when native currency is deposited to a creator's vault
    event NativeDeposited(address indexed creator, uint256 amount, uint256 timestamp);

    /// @notice Emitted when ERC20 tokens are deposited to a creator's vault
    event TokenDeposited(address indexed creator, address indexed token, uint256 amount, uint256 timestamp);

    /// @notice Emitted when a creator withdraws native currency
    event NativeWithdrawn(address indexed creator, uint256 amount, uint256 timestamp);

    /// @notice Emitted when a creator withdraws ERC20 tokens
    event TokenWithdrawn(address indexed creator, address indexed token, uint256 amount, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error InsufficientBalance(uint256 requested, uint256 available);
    error TransferFailed();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Deposit Functions ────────────────────────────────────────────────────

    /// @notice Deposit native currency into a creator's vault
    /// @param creator The creator address to credit
    function deposit(address creator) external payable nonReentrant {
        if (creator == address(0)) revert ZeroAddress();
        if (msg.value == 0) revert ZeroAmount();

        CreatorBalance storage bal = _nativeBalances[creator];
        bal.nativeBalance += msg.value;
        bal.totalDeposited += msg.value;
        totalNativeDistributed += msg.value;

        if (!_isCreator[creator]) {
            _isCreator[creator] = true;
            _creators.push(creator);
        }

        emit NativeDeposited(creator, msg.value, block.timestamp);
    }

    /// @notice Deposit ERC20 tokens into a creator's vault
    /// @param creator The creator address to credit
    /// @param token The ERC20 token address
    /// @param amount The amount of tokens
    function depositToken(address creator, IERC20 token, uint256 amount) external nonReentrant {
        if (creator == address(0)) revert ZeroAddress();
        if (address(token) == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();

        token.safeTransferFrom(msg.sender, address(this), amount);

        TokenBalance storage bal = _tokenBalances[creator][address(token)];
        bal.balance += amount;
        bal.totalDeposited += amount;

        if (!_isCreator[creator]) {
            _isCreator[creator] = true;
            _creators.push(creator);
        }

        emit TokenDeposited(creator, address(token), amount, block.timestamp);
    }

    // ── Withdrawal Functions (Pull-over-Push) ────────────────────────────────

    /// @notice Claim available native currency balance (pull-over-push)
    /// @param amount The amount to withdraw
    function claimRevenue(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();

        CreatorBalance storage bal = _nativeBalances[msg.sender];
        if (bal.nativeBalance < amount) revert InsufficientBalance(amount, bal.nativeBalance);

        bal.nativeBalance -= amount;
        bal.totalWithdrawn += amount;
        bal.lastClaimTime = block.timestamp;
        totalNativeWithdrawn += amount;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit NativeWithdrawn(msg.sender, amount, block.timestamp);
    }

    /// @notice Claim available ERC20 token balance (pull-over-push)
    /// @param token The ERC20 token address
    /// @param amount The amount to withdraw
    function claimTokenRevenue(address token, uint256 amount) external nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();

        TokenBalance storage bal = _tokenBalances[msg.sender][token];
        if (bal.balance < amount) revert InsufficientBalance(amount, bal.balance);

        bal.balance -= amount;
        bal.totalWithdrawn += amount;

        IERC20(token).safeTransfer(msg.sender, amount);

        emit TokenWithdrawn(msg.sender, token, amount, block.timestamp);
    }

    /// @notice Withdraw all available native currency balance
    function claimAllRevenue() external nonReentrant {
        CreatorBalance storage bal = _nativeBalances[msg.sender];
        uint256 amount = bal.nativeBalance;
        if (amount == 0) revert InsufficientBalance(0, 0);

        bal.nativeBalance = 0;
        bal.totalWithdrawn += amount;
        bal.lastClaimTime = block.timestamp;
        totalNativeWithdrawn += amount;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit NativeWithdrawn(msg.sender, amount, block.timestamp);
    }

    /// @notice Withdraw all available ERC20 token balance for a specific token
    /// @param token The ERC20 token address
    function claimAllTokenRevenue(address token) external nonReentrant {
        if (token == address(0)) revert ZeroAddress();

        TokenBalance storage bal = _tokenBalances[msg.sender][token];
        uint256 amount = bal.balance;
        if (amount == 0) revert InsufficientBalance(0, 0);

        bal.balance = 0;
        bal.totalWithdrawn += amount;

        IERC20(token).safeTransfer(msg.sender, amount);

        emit TokenWithdrawn(msg.sender, token, amount, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get native currency balance for a creator
    /// @param creator The creator address
    /// @return balance The available native balance
    function getBalance(address creator) external view returns (uint256) {
        return _nativeBalances[creator].nativeBalance;
    }

    /// @notice Get ERC20 token balance for a creator
    /// @param creator The creator address
    /// @param token The ERC20 token address
    /// @return balance The available token balance
    function getTokenBalance(address creator, address token) external view returns (uint256) {
        return _tokenBalances[creator][token].balance;
    }

    /// @notice Get full native balance info for a creator
    /// @param creator The creator address
    /// @return CreatorBalance struct
    function getCreatorNativeInfo(address creator) external view returns (CreatorBalance memory) {
        return _nativeBalances[creator];
    }

    /// @notice Get full token balance info for a creator
    /// @param creator The creator address
    /// @param token The ERC20 token address
    /// @return TokenBalance struct
    function getCreatorTokenInfo(address creator, address token) external view returns (TokenBalance memory) {
        return _tokenBalances[creator][token];
    }

    /// @notice Get total native currency distributed all-time
    /// @return Total distributed
    function getTotalDistributed() external view returns (uint256) {
        return totalNativeDistributed;
    }

    /// @notice Get total native currency withdrawn all-time
    /// @return Total withdrawn
    function getTotalWithdrawn() external view returns (uint256) {
        return totalNativeWithdrawn;
    }

    /// @notice Get the number of tracked creators
    /// @return count The creator count
    function getCreatorCount() external view returns (uint256) {
        return _creators.length;
    }

    /// @notice Get creator at index
    /// @param index The index
    /// @return creator The creator address
    function getCreatorAt(uint256 index) external view returns (address) {
        return _creators[index];
    }
}

contracts/foundry/FoundryDisputeResolver.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryDisputeResolver — Dispute Resolution for X3 Foundry
/// @notice Dispute resolution for dApp transactions with timelock-based resolution and escrow hold
/// @dev Uses timelock for resolution and ReentrancyGuard for safety
contract FoundryDisputeResolver is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Status of a dispute
    enum DisputeStatus {
        None,
        Raised,
        UnderReview,
        Resolved,
        Appealed,
        Escalated
    }

    /// @notice Resolution type
    enum ResolutionType {
        None,
        BuyerWins,
        SellerWins,
        Split,
        Cancelled
    }

    /// @notice Full dispute data
    struct Dispute {
        uint256 id;
        address disputant;          // The party raising the dispute
        address respondent;         // The other party
        address dapp;               // The dApp involved
        bytes32 transactionId;      // The transaction being disputed
        string reason;              // Reason for the dispute
        uint256 escrowAmount;       // Amount held in escrow (wei)
        DisputeStatus status;
        ResolutionType resolution;
        address resolver;           // Who resolved it
        uint256 raisedAt;
        uint256 resolvedAt;
        uint256 appealDeadline;     // Deadline for appeal
        string evidenceURI;         // URI to off-chain evidence
        string resolutionNote;      // Note on resolution
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Default timelock period for resolution (3 days)
    uint256 public constant DEFAULT_TIMELOCK = 3 days;

    /// @notice Appeal period after resolution (7 days)
    uint256 public constant APPEAL_PERIOD = 7 days;

    /// @notice Maximum dispute reason length
    uint256 public constant MAX_REASON_LENGTH = 1024;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Dispute ID => Dispute
    mapping(uint256 => Dispute) private _disputes;

    /// @notice Transaction ID => dispute ID
    mapping(bytes32 => uint256) private _disputeByTransaction;

    /// @notice Incremental dispute ID counter
    uint256 private _disputeCount;

    /// @notice Timelock period for resolution
    uint256 public timelockPeriod;

    /// @notice Address of the dispute resolver role
    address public disputeResolver;

    /// @notice Total escrow held
    uint256 public totalEscrowHeld;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a dispute is raised
    event DisputeRaised(
        uint256 indexed disputeId,
        address indexed disputant,
        address indexed respondent,
        bytes32 transactionId,
        uint256 escrowAmount,
        string reason,
        uint256 timestamp
    );

    /// @notice Emitted when a dispute is resolved
    event DisputeResolved(
        uint256 indexed disputeId,
        ResolutionType resolution,
        address indexed resolver,
        string note,
        uint256 timestamp
    );

    /// @notice Emitted when a dispute is appealed
    event DisputeAppealed(
        uint256 indexed disputeId,
        address indexed appellant,
        uint256 timestamp
    );

    /// @notice Emitted when timelock period is updated
    event TimelockUpdated(uint256 oldPeriod, uint256 newPeriod, uint256 timestamp);

    /// @notice Emitted when dispute resolver address is updated
    event DisputeResolverUpdated(address indexed oldResolver, address indexed newResolver, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error DisputeAlreadyExists(bytes32 transactionId);
    error DisputeNotFound(uint256 disputeId);
    error InvalidDisputeStatus(DisputeStatus current, DisputeStatus expected);
    error NotDisputant(uint256 disputeId);
    error NotResolver();
    error TimelockNotElapsed(uint256 deadline, uint256 current);
    error AppealPeriodExpired(uint256 deadline, uint256 current);
    error ReasonTooLong(uint256 length, uint256 max);
    error TransferFailed();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(address _disputeResolver) {
        _transferOwnership(msg.sender);
        if (_disputeResolver == address(0)) revert ZeroAddress();
        disputeResolver = _disputeResolver;
        timelockPeriod = DEFAULT_TIMELOCK;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the timelock period for dispute resolution
    /// @param newPeriod The new timelock period in seconds
    function setTimelock(uint256 newPeriod) external onlyOwner {
        if (newPeriod < 1 hours) revert("TIMELOCK_TOO_SHORT");
        uint256 oldPeriod = timelockPeriod;
        timelockPeriod = newPeriod;
        emit TimelockUpdated(oldPeriod, newPeriod, block.timestamp);
    }

    /// @notice Set the dispute resolver address
    /// @param newResolver The new resolver address
    function setDisputeResolver(address newResolver) external onlyOwner {
        if (newResolver == address(0)) revert ZeroAddress();
        address oldResolver = disputeResolver;
        disputeResolver = newResolver;
        emit DisputeResolverUpdated(oldResolver, newResolver, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Raise a new dispute with escrow hold
    /// @param respondent The other party in the dispute
    /// @param dapp The dApp involved
    /// @param transactionId The transaction ID being disputed
    /// @param reason The reason for the dispute
    /// @param evidenceURI URI to off-chain evidence
    /// @return disputeId The new dispute ID
    function raiseDispute(
        address respondent,
        address dapp,
        bytes32 transactionId,
        string calldata reason,
        string calldata evidenceURI
    ) external payable nonReentrant returns (uint256 disputeId) {
        if (respondent == address(0)) revert ZeroAddress();
        if (dapp == address(0)) revert ZeroAddress();
        if (msg.value == 0) revert ZeroAmount();
        if (bytes(reason).length > MAX_REASON_LENGTH) {
            revert ReasonTooLong(bytes(reason).length, MAX_REASON_LENGTH);
        }
        if (_disputeByTransaction[transactionId] != 0) {
            revert DisputeAlreadyExists(transactionId);
        }

        _disputeCount++;
        disputeId = _disputeCount;

        _disputes[disputeId] = Dispute({
            id: disputeId,
            disputant: msg.sender,
            respondent: respondent,
            dapp: dapp,
            transactionId: transactionId,
            reason: reason,
            escrowAmount: msg.value,
            status: DisputeStatus.Raised,
            resolution: ResolutionType.None,
            resolver: address(0),
            raisedAt: block.timestamp,
            resolvedAt: 0,
            appealDeadline: 0,
            evidenceURI: evidenceURI,
            resolutionNote: ""
        });

        _disputeByTransaction[transactionId] = disputeId;
        totalEscrowHeld += msg.value;

        emit DisputeRaised(disputeId, msg.sender, respondent, transactionId, msg.value, reason, block.timestamp);
    }

    /// @notice Resolve a dispute (only callable by resolver after timelock)
    /// @param disputeId The dispute ID
    /// @param resolution The resolution type
    /// @param note Resolution note
    function resolveDispute(
        uint256 disputeId,
        ResolutionType resolution,
        string calldata note
    ) external nonReentrant {
        if (msg.sender != disputeResolver && msg.sender != owner()) revert NotResolver();

        Dispute storage dispute = _disputes[disputeId];
        if (dispute.id == 0) revert DisputeNotFound(disputeId);
        if (dispute.status != DisputeStatus.Raised && dispute.status != DisputeStatus.UnderReview) {
            revert InvalidDisputeStatus(dispute.status, DisputeStatus.Raised);
        }

        // Enforce timelock
        uint256 deadline = dispute.raisedAt + timelockPeriod;
        if (block.timestamp < deadline) revert TimelockNotElapsed(deadline, block.timestamp);

        dispute.status = DisputeStatus.Resolved;
        dispute.resolution = resolution;
        dispute.resolver = msg.sender;
        dispute.resolvedAt = block.timestamp;
        dispute.appealDeadline = block.timestamp + APPEAL_PERIOD;
        dispute.resolutionNote = note;

        // Handle escrow distribution based on resolution
        _distributeEscrow(dispute);

        emit DisputeResolved(disputeId, resolution, msg.sender, note, block.timestamp);
    }

    /// @notice Appeal a resolved dispute
    /// @param disputeId The dispute ID to appeal
    function appealDispute(uint256 disputeId) external nonReentrant {
        Dispute storage dispute = _disputes[disputeId];
        if (dispute.id == 0) revert DisputeNotFound(disputeId);
        if (dispute.status != DisputeStatus.Resolved) {
            revert InvalidDisputeStatus(dispute.status, DisputeStatus.Resolved);
        }
        if (block.timestamp > dispute.appealDeadline) {
            revert AppealPeriodExpired(dispute.appealDeadline, block.timestamp);
        }
        if (msg.sender != dispute.disputant && msg.sender != dispute.respondent) {
            revert NotDisputant(disputeId);
        }

        dispute.status = DisputeStatus.Appealed;

        emit DisputeAppealed(disputeId, msg.sender, block.timestamp);
    }

    /// @notice Escalate an appealed dispute (admin function for final resolution)
    /// @param disputeId The dispute ID
    /// @param resolution The final resolution
    /// @param note Final resolution note
    function escalateDispute(
        uint256 disputeId,
        ResolutionType resolution,
        string calldata note
    ) external onlyOwner nonReentrant {
        Dispute storage dispute = _disputes[disputeId];
        if (dispute.id == 0) revert DisputeNotFound(disputeId);
        if (dispute.status != DisputeStatus.Appealed) {
            revert InvalidDisputeStatus(dispute.status, DisputeStatus.Appealed);
        }

        dispute.status = DisputeStatus.Escalated;
        dispute.resolution = resolution;
        dispute.resolver = msg.sender;
        dispute.resolvedAt = block.timestamp;
        dispute.resolutionNote = note;

        // Re-distribute escrow based on final resolution
        _distributeEscrow(dispute);

        emit DisputeResolved(disputeId, resolution, msg.sender, note, block.timestamp);
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Distribute escrow based on resolution
    function _distributeEscrow(Dispute storage dispute) internal {
        uint256 amount = dispute.escrowAmount;
        if (amount == 0) return;

        totalEscrowHeld -= amount;
        dispute.escrowAmount = 0;

        if (dispute.resolution == ResolutionType.BuyerWins) {
            // Return escrow to disputant
            (bool success,) = payable(dispute.disputant).call{value: amount}("");
            if (!success) revert TransferFailed();
        } else if (dispute.resolution == ResolutionType.SellerWins) {
            // Release escrow to respondent
            (bool success,) = payable(dispute.respondent).call{value: amount}("");
            if (!success) revert TransferFailed();
        } else if (dispute.resolution == ResolutionType.Split) {
            // Split 50/50
            uint256 half = amount / 2;
            (bool success1,) = payable(dispute.disputant).call{value: half}("");
            (bool success2,) = payable(dispute.respondent).call{value: amount - half}("");
            if (!success1 || !success2) revert TransferFailed();
        } else if (dispute.resolution == ResolutionType.Cancelled) {
            // Return to disputant
            (bool success,) = payable(dispute.disputant).call{value: amount}("");
            if (!success) revert TransferFailed();
        }
        // ResolutionType.None: escrow stays (should not happen)
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get dispute details by ID
    /// @param disputeId The dispute ID
    /// @return Dispute struct
    function getDispute(uint256 disputeId) external view returns (Dispute memory) {
        if (disputeId == 0 || disputeId > _disputeCount) revert DisputeNotFound(disputeId);
        return _disputes[disputeId];
    }

    /// @notice Get dispute ID by transaction ID
    /// @param transactionId The transaction ID
    /// @return disputeId The dispute ID (0 if none)
    function getDisputeByTransaction(bytes32 transactionId) external view returns (uint256) {
        return _disputeByTransaction[transactionId];
    }

    /// @notice Get total number of disputes
    /// @return count The dispute count
    function getDisputeCount() external view returns (uint256) {
        return _disputeCount;
    }

    /// @notice Get disputes for a specific address (as disputant or respondent)
    /// @param participant The address to query
    /// @return disputeIds Array of dispute IDs
    function getDisputesByParticipant(address participant) external view returns (uint256[] memory disputeIds) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _disputeCount; i++) {
            if (_disputes[i].disputant == participant || _disputes[i].respondent == participant) {
                count++;
            }
        }
        disputeIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _disputeCount; i++) {
            if (_disputes[i].disputant == participant || _disputes[i].respondent == participant) {
                disputeIds[idx] = i;
                idx++;
            }
        }
    }

    /// @notice Get disputes by status
    /// @param status The dispute status to filter
    /// @return disputeIds Array of dispute IDs
    function getDisputesByStatus(DisputeStatus status) external view returns (uint256[] memory disputeIds) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _disputeCount; i++) {
            // slither-disable-next-line incorrect-equality
            if (_disputes[i].status == status) count++;
        }
        disputeIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _disputeCount; i++) {
            // slither-disable-next-line incorrect-equality
            if (_disputes[i].status == status) {
                disputeIds[idx] = i;
                idx++;
            }
        }
    }
}

contracts/foundry/FoundryFeeConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title FoundryFeeConfig — Fee Configuration Manager for X3 Foundry
/// @notice Manages fee configuration for each dApp with minimum platform fee enforcement
/// @dev Stores RevenueConfig struct with platform_fee_bps, creator_fee_bps, etc.
contract FoundryFeeConfig is Ownable {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Revenue configuration for a dApp
    struct RevenueConfig {
        uint256 platformFeeBps;     // Platform fee in basis points (e.g., 250 = 2.5%)
        uint256 creatorFeeBps;      // Creator fee in basis points
        uint256 referralFeeBps;     // Referral fee in basis points
        uint256 royaltyFeeBps;      // Royalty fee in basis points
        uint256 subscriptionFee;    // Fixed subscription fee (in wei)
        bool isActive;              // Whether this config is active
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Maximum basis points (100%)
    uint256 public constant MAX_BPS = 10000;

    /// @notice Default platform minimum fee in basis points (2.5%)
    uint256 public constant DEFAULT_MIN_PLATFORM_FEE_BPS = 250;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice dApp address => RevenueConfig
    mapping(address => RevenueConfig) private _feeConfigs;

    /// @notice Minimum platform fee in basis points (enforced globally)
    uint256 private _minPlatformFeeBps;

    /// @notice Whether a dApp has a fee config set
    mapping(address => bool) private _hasConfig;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a fee config is set for a dApp
    event FeeConfigSet(
        address indexed dapp,
        uint256 platformFeeBps,
        uint256 creatorFeeBps,
        uint256 referralFeeBps,
        uint256 royaltyFeeBps,
        uint256 subscriptionFee,
        uint256 timestamp
    );

    /// @notice Emitted when the minimum platform fee is updated
    event MinPlatformFeeUpdated(uint256 oldFeeBps, uint256 newFeeBps, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error InvalidBps(uint256 bps);
    error PlatformFeeTooLow(uint256 provided, uint256 minimum);
    error TotalFeeExceedsMax(uint256 total, uint256 maxBps);
    error ConfigNotSet(address dapp);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
        _minPlatformFeeBps = DEFAULT_MIN_PLATFORM_FEE_BPS;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set or update the fee configuration for a dApp
    /// @param dapp The dApp contract address
    /// @param config The RevenueConfig to set
    function setFeeConfig(address dapp, RevenueConfig calldata config) external onlyOwner {
        if (dapp == address(0)) revert ZeroAddress();

        _validateFeeConfig(config);

        _feeConfigs[dapp] = config;
        _hasConfig[dapp] = true;

        emit FeeConfigSet(
            dapp,
            config.platformFeeBps,
            config.creatorFeeBps,
            config.referralFeeBps,
            config.royaltyFeeBps,
            config.subscriptionFee,
            block.timestamp
        );
    }

    /// @notice Set the global minimum platform fee (in basis points)
    /// @param newFeeBps The new minimum platform fee in basis points
    function setPlatformMinFee(uint256 newFeeBps) external onlyOwner {
        if (newFeeBps > MAX_BPS) revert InvalidBps(newFeeBps);

        uint256 oldFeeBps = _minPlatformFeeBps;
        _minPlatformFeeBps = newFeeBps;

        emit MinPlatformFeeUpdated(oldFeeBps, newFeeBps, block.timestamp);
    }

    // ── Public Functions ─────────────────────────────────────────────────────

    /// @notice Validate a RevenueConfig against business rules
    /// @param config The RevenueConfig to validate
    /// @return True if valid, reverts otherwise
    function validateFeeConfig(RevenueConfig calldata config) external view returns (bool) {
        _validateFeeConfig(config);
        return true;
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Internal validation logic for RevenueConfig
    function _validateFeeConfig(RevenueConfig memory config) internal view {
        if (config.platformFeeBps > MAX_BPS) revert InvalidBps(config.platformFeeBps);
        if (config.creatorFeeBps > MAX_BPS) revert InvalidBps(config.creatorFeeBps);
        if (config.referralFeeBps > MAX_BPS) revert InvalidBps(config.referralFeeBps);
        if (config.royaltyFeeBps > MAX_BPS) revert InvalidBps(config.royaltyFeeBps);

        // Enforce minimum platform fee
        if (config.platformFeeBps < _minPlatformFeeBps) {
            revert PlatformFeeTooLow(config.platformFeeBps, _minPlatformFeeBps);
        }

        // Ensure total fees don't exceed 100%
        uint256 total = config.platformFeeBps + config.creatorFeeBps
            + config.referralFeeBps + config.royaltyFeeBps;
        if (total > MAX_BPS) revert TotalFeeExceedsMax(total, MAX_BPS);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get the fee configuration for a dApp
    /// @param dapp The dApp contract address
    /// @return RevenueConfig struct
    function getFeeConfig(address dapp) external view returns (RevenueConfig memory) {
        if (!_hasConfig[dapp]) revert ConfigNotSet(dapp);
        return _feeConfigs[dapp];
    }

    /// @notice Get the global minimum platform fee in basis points
    /// @return The minimum platform fee in bps
    function getPlatformMinFee() external view returns (uint256) {
        return _minPlatformFeeBps;
    }

    /// @notice Check if a dApp has a fee config set
    /// @param dapp The dApp contract address
    /// @return True if config exists
    function hasFeeConfig(address dapp) external view returns (bool) {
        return _hasConfig[dapp];
    }

    /// @notice Get the effective fee breakdown for a given amount
    /// @param dapp The dApp contract address
    /// @param amount The transaction amount
    /// @return platformFee The platform fee amount
    /// @return creatorFee The creator fee amount
    /// @return referralFee The referral fee amount
    /// @return royaltyFee The royalty fee amount
    function calculateFees(
        address dapp,
        uint256 amount
    ) external view returns (
        uint256 platformFee,
        uint256 creatorFee,
        uint256 referralFee,
        uint256 royaltyFee
    ) {
        if (!_hasConfig[dapp]) revert ConfigNotSet(dapp);
        RevenueConfig storage config = _feeConfigs[dapp];

        platformFee = (amount * config.platformFeeBps) / MAX_BPS;
        creatorFee = (amount * config.creatorFeeBps) / MAX_BPS;
        referralFee = (amount * config.referralFeeBps) / MAX_BPS;
        royaltyFee = (amount * config.royaltyFeeBps) / MAX_BPS;
    }
}

