// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryForkRemix — Fork/Remix System for X3 Foundry
/// @notice Fork/remix system that tracks fork lineage and handles remix royalties
/// @dev Supports forking dApps and remixing templates with lineage tracking
contract FoundryForkRemix is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Represents a fork or remix
    struct Fork {
        uint256 id;
        address originalDapp;       // The original dApp that was forked
        address forkedDapp;         // The new forked dApp address
        address forkCreator;        // Who created the fork
        uint256 originalTemplateId; // Template ID if forked from a template
        string name;
        string description;
        uint256 remixRoyaltyBps;    // Royalty for original creator in basis points
        uint256 createdAt;
        bool isActive;
    }

    /// @notice Lineage node for tracking ancestry
    struct LineageNode {
        uint256 forkId;
        address dappAddress;
        address parentDapp;
        uint256 depth;              // How deep in the lineage (0 = original)
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Maximum basis points (100%)
    uint256 public constant MAX_BPS = 10000;

    /// @notice Maximum remix royalty basis points (25%)
    uint256 public constant MAX_REMIX_ROYALTY_BPS = 2500;

    /// @notice Default remix royalty basis points (5%)
    uint256 public constant DEFAULT_REMIX_ROYALTY_BPS = 500;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Fork ID => Fork
    mapping(uint256 => Fork) private _forks;

    /// @notice dApp address => fork ID
    mapping(address => uint256) private _forkIdByDapp;

    /// @notice Original dApp => array of fork IDs
    mapping(address => uint256[]) private _forksOfOriginal;

    /// @notice dApp address => LineageNode
    mapping(address => LineageNode) private _lineage;

    /// @notice dApp address => remix royalty BPS (set by original creator)
    mapping(address => uint256) private _remixRoyalties;

    /// @notice dApp address => accumulated remix revenue
    mapping(address => uint256) private _remixRevenue;

    /// @notice Incremental fork ID counter
    uint256 private _forkCount;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a dApp is forked
    event AppForked(
        uint256 indexed forkId,
        address indexed originalDapp,
        address indexed forkedDapp,
        address forkCreator,
        string name,
        uint256 timestamp
    );

    /// @notice Emitted when a template is remixed
    event TemplateRemixed(
        uint256 indexed forkId,
        uint256 indexed templateId,
        address indexed forkedDapp,
        address remixCreator,
        uint256 timestamp
    );

    /// @notice Emitted when remix royalty is set
    event RemixRoyaltySet(
        address indexed dapp,
        uint256 royaltyBps,
        uint256 timestamp
    );

    /// @notice Emitted when remix revenue is claimed
    event RemixRevenueClaimed(
        address indexed dapp,
        address indexed claimer,
        uint256 amount,
        uint256 timestamp
    );

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyName();
    error AlreadyForked(address dapp);
    error ForkNotFound(uint256 forkId);
    error InvalidRoyaltyBps(uint256 bps);
    error NoRevenueToClaim();
    error TransferFailed();
    error MaxDepthExceeded(uint256 depth);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Fork an existing dApp
    /// @param originalDapp The original dApp address to fork
    /// @param forkedDapp The new forked dApp address
    /// @param name Name for the fork
    /// @param description Description for the fork
    /// @return forkId The new fork ID
    function forkApp(
        address originalDapp,
        address forkedDapp,
        string calldata name,
        string calldata description
    ) external nonReentrant returns (uint256 forkId) {
        if (originalDapp == address(0)) revert ZeroAddress();
        if (forkedDapp == address(0)) revert ZeroAddress();
        if (bytes(name).length == 0) revert EmptyName();
        if (_forkIdByDapp[forkedDapp] != 0) revert AlreadyForked(forkedDapp);

        // Check lineage depth
        uint256 parentDepth = _lineage[originalDapp].depth;
        if (parentDepth >= 10) revert MaxDepthExceeded(parentDepth);

        _forkCount++;
        forkId = _forkCount;

        uint256 royaltyBps = _remixRoyalties[originalDapp] > 0
            ? _remixRoyalties[originalDapp]
            : DEFAULT_REMIX_ROYALTY_BPS;

        _forks[forkId] = Fork({
            id: forkId,
            originalDapp: originalDapp,
            forkedDapp: forkedDapp,
            forkCreator: msg.sender,
            originalTemplateId: 0,
            name: name,
            description: description,
            remixRoyaltyBps: royaltyBps,
            createdAt: block.timestamp,
            isActive: true
        });

        _forkIdByDapp[forkedDapp] = forkId;
        _forksOfOriginal[originalDapp].push(forkId);

        // Set lineage
        _lineage[forkedDapp] = LineageNode({
            forkId: forkId,
            dappAddress: forkedDapp,
            parentDapp: originalDapp,
            depth: parentDepth + 1
        });

        emit AppForked(forkId, originalDapp, forkedDapp, msg.sender, name, block.timestamp);
    }

    /// @notice Remix a template (create a new dApp from a template)
    /// @param templateId The template ID
    /// @param remixedDapp The new dApp address
    /// @param name Name for the remix
    /// @param description Description for the remix
    /// @return forkId The new fork ID
    function remixTemplate(
        uint256 templateId,
        address remixedDapp,
        string calldata name,
        string calldata description
    ) external nonReentrant returns (uint256 forkId) {
        if (templateId == 0) revert("INVALID_TEMPLATE");
        if (remixedDapp == address(0)) revert ZeroAddress();
        if (bytes(name).length == 0) revert EmptyName();
        if (_forkIdByDapp[remixedDapp] != 0) revert AlreadyForked(remixedDapp);

        _forkCount++;
        forkId = _forkCount;

        _forks[forkId] = Fork({
            id: forkId,
            originalDapp: address(0),
            forkedDapp: remixedDapp,
            forkCreator: msg.sender,
            originalTemplateId: templateId,
            name: name,
            description: description,
            remixRoyaltyBps: 0,
            createdAt: block.timestamp,
            isActive: true
        });

        _forkIdByDapp[remixedDapp] = forkId;

        // Set lineage (template remixes start at depth 0)
        _lineage[remixedDapp] = LineageNode({
            forkId: forkId,
            dappAddress: remixedDapp,
            parentDapp: address(0),
            depth: 0
        });

        emit TemplateRemixed(forkId, templateId, remixedDapp, msg.sender, block.timestamp);
    }

    /// @notice Set the remix royalty for a dApp (by original creator)
    /// @param dapp The dApp address
    /// @param royaltyBps The royalty in basis points
    function setRemixRoyalty(address dapp, uint256 royaltyBps) external {
        if (dapp == address(0)) revert ZeroAddress();
        if (royaltyBps > MAX_REMIX_ROYALTY_BPS) revert InvalidRoyaltyBps(royaltyBps);

        // Only the original creator or owner can set royalty
        uint256 forkId = _forkIdByDapp[dapp];
        if (forkId != 0) {
            Fork storage fork = _forks[forkId];
            if (fork.forkCreator != msg.sender && owner() != msg.sender) {
                revert("NOT_AUTHORIZED");
            }
        } else if (owner() != msg.sender) {
            revert("NOT_AUTHORIZED");
        }

        _remixRoyalties[dapp] = royaltyBps;

        emit RemixRoyaltySet(dapp, royaltyBps, block.timestamp);
    }

    /// @notice Record remix revenue (called when a fork generates revenue)
    /// @param forkedDapp The forked dApp that generated revenue
    /// @param revenueAmount The revenue amount
    function recordRemixRevenue(address forkedDapp, uint256 revenueAmount) external payable nonReentrant {
        if (forkedDapp == address(0)) revert ZeroAddress();
        uint256 forkId = _forkIdByDapp[forkedDapp];
        if (forkId == 0) revert ForkNotFound(forkId);

        Fork storage fork = _forks[forkId];
        if (!fork.isActive) revert("FORK_INACTIVE");

        uint256 actualAmount = revenueAmount > 0 ? revenueAmount : msg.value;
        if (actualAmount == 0) revert("ZERO_AMOUNT");

        uint256 royaltyAmount = (actualAmount * fork.remixRoyaltyBps) / MAX_BPS;

        if (royaltyAmount > 0 && fork.originalDapp != address(0)) {
            _remixRevenue[fork.originalDapp] += royaltyAmount;
        }
    }

    /// @notice Claim accumulated remix revenue (pull-over-push)
    /// @param amount The amount to claim
    function claimRemixRevenue(uint256 amount) external nonReentrant {
        if (amount == 0) revert("ZERO_AMOUNT");
        if (_remixRevenue[msg.sender] < amount) revert NoRevenueToClaim();

        _remixRevenue[msg.sender] -= amount;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit RemixRevenueClaimed(msg.sender, msg.sender, amount, block.timestamp);
    }

    /// @notice Claim all accumulated remix revenue
    function claimAllRemixRevenue() external nonReentrant {
        uint256 amount = _remixRevenue[msg.sender];
        if (amount == 0) revert NoRevenueToClaim();

        _remixRevenue[msg.sender] = 0;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit RemixRevenueClaimed(msg.sender, msg.sender, amount, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get fork details by ID
    /// @param forkId The fork ID
    /// @return Fork struct
    function getFork(uint256 forkId) external view returns (Fork memory) {
        if (forkId == 0 || forkId > _forkCount) revert ForkNotFound(forkId);
        return _forks[forkId];
    }

    /// @notice Get fork ID by dApp address
    /// @param dapp The dApp address
    /// @return forkId The fork ID (0 if not a fork)
    function getForkIdByDapp(address dapp) external view returns (uint256) {
        return _forkIdByDapp[dapp];
    }

    /// @notice Get the lineage of a dApp (ancestry chain)
    /// @param dapp The dApp address
    /// @return lineage Array of LineageNode
    function getLineage(address dapp) external view returns (LineageNode[] memory lineage) {
        // Walk up the lineage tree
        uint256 depth = _lineage[dapp].depth;
        lineage = new LineageNode[](depth + 1);

        address current = dapp;
        for (uint256 i = 0; i <= depth; i++) {
            lineage[i] = _lineage[current];
            current = lineage[i].parentDapp;
        }
    }

    /// @notice Get all forks of an original dApp
    /// @param originalDapp The original dApp address
    /// @return forks Array of Fork structs
    function getForksOfOriginal(address originalDapp) external view returns (Fork[] memory forks) {
        uint256[] storage forkIds = _forksOfOriginal[originalDapp];
        uint256 len = forkIds.length;
        forks = new Fork[](len);
        for (uint256 i = 0; i < len; i++) {
            forks[i] = _forks[forkIds[i]];
        }
    }

    /// @notice Get the remix royalty for a dApp
    /// @param dapp The dApp address
    /// @return royaltyBps The royalty in basis points
    function getRemixRoyalty(address dapp) external view returns (uint256) {
        return _remixRoyalties[dapp];
    }

    /// @notice Get accumulated remix revenue for a dApp
    /// @param dapp The dApp address
    /// @return revenue The accumulated revenue
    function getRemixRevenue(address dapp) external view returns (uint256) {
        return _remixRevenue[dapp];
    }

    /// @notice Get total number of forks
    /// @return count The fork count
    function getForkCount() external view returns (uint256) {
        return _forkCount;
    }

    /// @notice Get lineage depth of a dApp
    /// @param dapp The dApp address
    /// @return depth The depth
    function getLineageDepth(address dapp) external view returns (uint256) {
        return _lineage[dapp].depth;
    }
}

contracts/foundry/FoundryGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/// @title FoundryGovernance — Governance Controls for X3 Foundry
/// @notice Governance controls with proposal, voting, execution, timelock, and pause
/// @dev Timelock for fee increases, emergency pause for security, transparent proposal records
contract FoundryGovernance is Ownable, ReentrancyGuard, Pausable {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Status of a proposal
    enum ProposalStatus {
        Pending,
        Active,
        Succeeded,
        Defeated,
        Queued,
        Executed,
        Cancelled
    }

    /// @notice A governance proposal
    struct Proposal {
        uint256 id;
        address proposer;
        string title;
        string description;
        bytes[] calldatas;              // Calldata for each action
        address[] targets;              // Target addresses for each action
        uint256[] values;               // Native currency values for each action
        uint256 startTime;              // When voting starts
        uint256 endTime;                // When voting ends
        uint256 executionTime;          // When queued for execution (after timelock)
        uint256 forVotes;
        uint256 againstVotes;
        ProposalStatus status;
        bool executed;
        uint256 createdAt;
    }

    /// @notice A vote cast by a voter
    struct Vote {
        bool support;       // true = for, false = against
        uint256 weight;
        uint256 timestamp;
        bool voted;
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Default voting period (7 days)
    uint256 public constant DEFAULT_VOTING_PERIOD = 7 days;

    /// @notice Default timelock period (2 days)
    uint256 public constant DEFAULT_TIMELOCK = 2 days;

    /// @notice Minimum voting period (1 day)
    uint256 public constant MIN_VOTING_PERIOD = 1 days;

    /// @notice Maximum voting period (30 days)
    uint256 public constant MAX_VOTING_PERIOD = 30 days;

    /// @notice Minimum timelock (1 hour)
    uint256 public constant MIN_TIMELOCK = 1 hours;

    /// @notice Maximum timelock (30 days)
    uint256 public constant MAX_TIMELOCK = 30 days;

    /// @notice Maximum number of actions per proposal
    uint256 public constant MAX_ACTIONS = 10;

    /// @notice Quorum basis points (e.g., 400 = 4% of total voting power)
    uint256 public constant QUORUM_BPS = 400;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Proposal ID => Proposal
    mapping(uint256 => Proposal) private _proposals;

    /// @notice Proposal ID => voter address => Vote
    mapping(uint256 => mapping(address => Vote)) private _votes;

    /// @notice Incremental proposal ID counter
    uint256 private _proposalCount;

    /// @notice Voting period in seconds
    uint256 public votingPeriod;

    /// @notice Timelock period in seconds
    uint256 public governanceTimelock;

    /// @notice Minimum quorum (in basis points of total voting power)
    uint256 public quorumBps;

    /// @notice Total voting power (simplified - in production this would be token-based)
    uint256 public totalVotingPower;

    /// @notice Mapping of addresses with voting power
    mapping(address => uint256) public votingPower;

    /// @notice Whether fee increases are timelocked
    bool public feeIncreaseTimelocked;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a proposal is created
    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string title,
        uint256 startTime,
        uint256 endTime,
        uint256 timestamp
    );

    /// @notice Emitted when a vote is cast
    event VoteCast(
        uint256 indexed proposalId,
        address indexed voter,
        bool support,
        uint256 weight,
        uint256 timestamp
    );

    /// @notice Emitted when a proposal is executed
    event ProposalExecuted(uint256 indexed proposalId, uint256 timestamp);

    /// @notice Emitted when a proposal is cancelled
    event ProposalCancelled(uint256 indexed proposalId, uint256 timestamp);

    /// @notice Emitted when voting period is updated
    event VotingPeriodUpdated(uint256 oldPeriod, uint256 newPeriod, uint256 timestamp);

    /// @notice Emitted when timelock is updated
    event TimelockUpdated(uint256 oldTimelock, uint256 newTimelock, uint256 timestamp);

    /// @notice Emitted when quorum is updated
    event QuorumBpsUpdated(uint256 oldBps, uint256 newBps, uint256 timestamp);

    /// @notice Emitted when voting power is set
    event VotingPowerSet(address indexed voter, uint256 oldPower, uint256 newPower, uint256 timestamp);

    /// @notice Emitted when contract is paused/unpaused
    event PausedUpdated(bool isPaused, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyTitle();
    error NoActions();
    error TooManyActions(uint256 count, uint256 max);
    error ProposalNotFound(uint256 proposalId);
    error InvalidProposalStatus(ProposalStatus current, ProposalStatus expected);
    error VotingNotActive(uint256 now, uint256 start, uint256 end);
    error AlreadyVoted(uint256 proposalId, address voter);
    error NoVotingPower();
    error QuorumNotMet(uint256 forVotes, uint256 againstVotes, uint256 quorum);
    error TimelockNotElapsed(uint256 deadline, uint256 current);
    error ExecutionFailed(uint256 actionIndex);
    error InvalidVotingPeriod(uint256 period);
    error InvalidTimelock(uint256 timelock);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
        votingPeriod = DEFAULT_VOTING_PERIOD;
        governanceTimelock = DEFAULT_TIMELOCK;
        quorumBps = QUORUM_BPS;
        feeIncreaseTimelocked = true;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the voting period
    /// @param newPeriod The new voting period in seconds
    function setVotingPeriod(uint256 newPeriod) external onlyOwner {
        if (newPeriod < MIN_VOTING_PERIOD || newPeriod > MAX_VOTING_PERIOD) {
            revert InvalidVotingPeriod(newPeriod);
        }
        uint256 oldPeriod = votingPeriod;
        votingPeriod = newPeriod;
        emit VotingPeriodUpdated(oldPeriod, newPeriod, block.timestamp);
    }

    /// @notice Set the timelock period
    /// @param newTimelock The new timelock in seconds
    function setTimelock(uint256 newTimelock) external onlyOwner {
        if (newTimelock < MIN_TIMELOCK || newTimelock > MAX_TIMELOCK) {
            revert InvalidTimelock(newTimelock);
        }
        uint256 oldTimelock = governanceTimelock;
        governanceTimelock = newTimelock;
        emit TimelockUpdated(oldTimelock, newTimelock, block.timestamp);
    }

    /// @notice Set quorum basis points
    /// @param newQuorumBps The new quorum in basis points
    function setQuorumBps(uint256 newQuorumBps) external onlyOwner {
        if (newQuorumBps > 5000) revert("QUORUM_TOO_HIGH"); // Max 50%
        uint256 oldBps = quorumBps;
        quorumBps = newQuorumBps;
        emit QuorumBpsUpdated(oldBps, newQuorumBps, block.timestamp);
    }

    /// @notice Set voting power for an address
    /// @param voter The voter address
    /// @param power The voting power
    function setVotingPower(address voter, uint256 power) external onlyOwner {
        if (voter == address(0)) revert ZeroAddress();
        uint256 oldPower = votingPower[voter];
        totalVotingPower = totalVotingPower - oldPower + power;
        votingPower[voter] = power;
        emit VotingPowerSet(voter, oldPower, power, block.timestamp);
    }

    /// @notice Enable/disable fee increase timelock
    /// @param locked Whether fee increases require timelock
    function setFeeIncreaseTimelock(bool locked) external onlyOwner {
        feeIncreaseTimelocked = locked;
    }

    /// @notice Pause the contract (emergency stop)
    function pause() external onlyOwner {
        _pause();
        emit PausedUpdated(true, block.timestamp);
    }

    /// @notice Unpause the contract
    function unpause() external onlyOwner {
        _unpause();
        emit PausedUpdated(false, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Create a new governance proposal
    /// @param title Proposal title
    /// @param description Proposal description
    /// @param targets Target addresses for each action
    /// @param values Native currency values for each action
    /// @param calldatas Calldata for each action
    /// @return proposalId The new proposal ID
    function propose(
        string calldata title,
        string calldata description,
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas
    ) external whenNotPaused returns (uint256 proposalId) {
        if (bytes(title).length == 0) revert EmptyTitle();
        if (targets.length == 0) revert NoActions();
        if (targets.length > MAX_ACTIONS) revert TooManyActions(targets.length, MAX_ACTIONS);
        if (targets.length != values.length || targets.length != calldatas.length) {
            revert("ARRAY_LENGTH_MISMATCH");
        }

        // Check proposer has voting power
        if (votingPower[msg.sender] == 0) revert NoVotingPower();

        _proposalCount++;
        proposalId = _proposalCount;

        _proposals[proposalId] = Proposal({
            id: proposalId,
            proposer: msg.sender,
            title: title,
            description: description,
            calldatas: calldatas,
            targets: targets,
            values: values,
            startTime: block.timestamp,
            endTime: block.timestamp + votingPeriod,
            executionTime: 0,
            forVotes: 0,
            againstVotes: 0,
            status: ProposalStatus.Active,
            executed: false,
            createdAt: block.timestamp
        });

        emit ProposalCreated(proposalId, msg.sender, title, block.timestamp, block.timestamp + votingPeriod, block.timestamp);
    }

    /// @notice Cast a vote on a proposal
    /// @param proposalId The proposal ID
    /// @param support True for "for", false for "against"
    function vote(uint256 proposalId, bool support) external whenNotPaused {
        if (proposalId == 0 || proposalId > _proposalCount) revert ProposalNotFound(proposalId);

        Proposal storage proposal = _proposals[proposalId];
        if (proposal.status != ProposalStatus.Active) {
            revert InvalidProposalStatus(proposal.status, ProposalStatus.Active);
        }
        if (block.timestamp < proposal.startTime || block.timestamp > proposal.endTime) {
            revert VotingNotActive(block.timestamp, proposal.startTime, proposal.endTime);
        }
        if (_votes[proposalId][msg.sender].voted) {
            revert AlreadyVoted(proposalId, msg.sender);
        }

        uint256 weight = votingPower[msg.sender];
        if (weight == 0) revert NoVotingPower();

        _votes[proposalId][msg.sender] = Vote({
            support: support,
            weight: weight,
            timestamp: block.timestamp,
            voted: true
        });

        if (support) {
            proposal.forVotes += weight;
        } else {
            proposal.againstVotes += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight, block.timestamp);
    }

    /// @notice Queue a successful proposal for execution (after timelock)
    /// @param proposalId The proposal ID
    function queueProposal(uint256 proposalId) external {
        if (proposalId == 0 || proposalId > _proposalCount) revert ProposalNotFound(proposalId);

        Proposal storage proposal = _proposals[proposalId];
        if (proposal.status != ProposalStatus.Active) {
            revert InvalidProposalStatus(proposal.status, ProposalStatus.Active);
        }
        if (block.timestamp < proposal.endTime) revert("VOTING_NOT_ENDED");

        // Check quorum
        uint256 totalVotes = proposal.forVotes + proposal.againstVotes;
        uint256 quorum = (totalVotingPower * quorumBps) / 10000;
        if (totalVotes < quorum) revert QuorumNotMet(proposal.forVotes, proposal.againstVotes, quorum);

        if (proposal.forVotes <= proposal.againstVotes) {
            proposal.status = ProposalStatus.Defeated;
            revert("PROPOSAL_DEFEATED");
        }

        proposal.status = ProposalStatus.Succeeded;
        proposal.executionTime = block.timestamp + governanceTimelock;
        proposal.status = ProposalStatus.Queued;
    }

    /// @notice Execute a queued proposal
    /// @param proposalId The proposal ID
    function execute(uint256 proposalId) external nonReentrant whenNotPaused {
        if (proposalId == 0 || proposalId > _proposalCount) revert ProposalNotFound(proposalId);

        Proposal storage proposal = _proposals[proposalId];
        if (proposal.status != ProposalStatus.Queued) {
            revert InvalidProposalStatus(proposal.status, ProposalStatus.Queued);
        }
        if (block.timestamp < proposal.executionTime) {
            revert TimelockNotElapsed(proposal.executionTime, block.timestamp);
        }
        if (proposal.executed) revert("ALREADY_EXECUTED");

        proposal.executed = true;
        proposal.status = ProposalStatus.Executed;

        // Execute each action
        for (uint256 i = 0; i < proposal.targets.length; i++) {
            (bool success,) = proposal.targets[i].call{value: proposal.values[i]}(proposal.calldatas[i]);
            if (!success) revert ExecutionFailed(i);
        }

        emit ProposalExecuted(proposalId, block.timestamp);
    }

    /// @notice Cancel a proposal (only proposer or owner)
    /// @param proposalId The proposal ID
    function cancelProposal(uint256 proposalId) external {
        if (proposalId == 0 || proposalId > _proposalCount) revert ProposalNotFound(proposalId);

        Proposal storage proposal = _proposals[proposalId];
        if (proposal.proposer != msg.sender && owner() != msg.sender) {
            revert("NOT_AUTHORIZED");
        }
        if (proposal.status == ProposalStatus.Executed) {
            revert InvalidProposalStatus(proposal.status, ProposalStatus.Executed);
        }

        proposal.status = ProposalStatus.Cancelled;

        emit ProposalCancelled(proposalId, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get proposal details by ID
    /// @param proposalId The proposal ID
    /// @return Proposal struct
    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        if (proposalId == 0 || proposalId > _proposalCount) revert ProposalNotFound(proposalId);
        return _proposals[proposalId];
    }

    /// @notice Get total number of proposals
    /// @return count The proposal count
    function getProposalCount() external view returns (uint256) {
        return _proposalCount;
    }

    /// @notice Get vote details for a voter on a proposal
    /// @param proposalId The proposal ID
    /// @param voter The voter address
    /// @return Vote struct
    function getVote(uint256 proposalId, address voter) external view returns (Vote memory) {
        return _votes[proposalId][voter];
    }

    /// @notice Check if a voter has voted on a proposal
    /// @param proposalId The proposal ID
    /// @param voter The voter address
    /// @return True if voted
    function hasVoted(uint256 proposalId, address voter) external view returns (bool) {
        return _votes[proposalId][voter].voted;
    }

    /// @notice Get proposals by status
    /// @param status The proposal status
    /// @return proposalIds Array of proposal IDs
    function getProposalsByStatus(ProposalStatus status) external view returns (uint256[] memory proposalIds) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _proposalCount; i++) {
            // slither-disable-next-line incorrect-equality
            if (_proposals[i].status == status) count++;
        }
        proposalIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _proposalCount; i++) {
            // slither-disable-next-line incorrect-equality
            if (_proposals[i].status == status) {
                proposalIds[idx] = i;
                idx++;
            }
        }
    }

    /// @notice Get proposals by proposer
    /// @param proposer The proposer address
    /// @return proposalIds Array of proposal IDs
    function getProposalsByProposer(address proposer) external view returns (uint256[] memory proposalIds) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _proposalCount; i++) {
            if (_proposals[i].proposer == proposer) count++;
        }
        proposalIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _proposalCount; i++) {
            if (_proposals[i].proposer == proposer) {
                proposalIds[idx] = i;
                idx++;
            }
        }
    }

    /// @notice Get the current governance parameters
    /// @return _votingPeriod The voting period
    /// @return _timelock The timelock period
    /// @return _quorumBps The quorum basis points
    /// @return _totalVotingPower The total voting power
    /// @return _feeIncreaseTimelocked Whether fee increases are timelocked
    function getGovernanceParameters() external view returns (
        uint256 _votingPeriod,
        uint256 _timelock,
        uint256 _quorumBps,
        uint256 _totalVotingPower,
        bool _feeIncreaseTimelocked
    ) {
        return (votingPeriod, governanceTimelock, quorumBps, totalVotingPower, feeIncreaseTimelocked);
    }
}

contracts/foundry/FoundryMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryMarketplace — dApp Marketplace for X3 Foundry
/// @notice Marketplace listing contract for dApps with search, categories, and featured listings
/// @dev Stores all marketplace metadata on-chain
contract FoundryMarketplace is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Full marketplace listing
    struct Listing {
        uint256 id;
        address dappAddress;
        address seller;
        string title;
        string description;
        string category;
        string tags;                // Comma-separated tags
        string metadataURI;         // URI to off-chain metadata
        uint256 price;              // Price in wei (0 = free)
        bool isActive;
        bool isFeatured;
        uint256 featuredUntil;      // Timestamp when featured expires
        uint256 createdAt;
        uint256 updatedAt;
        uint256 totalSales;
        uint256 totalRevenue;
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Listing ID => Listing
    mapping(uint256 => Listing) private _listings;

    /// @notice dApp address => listing ID
    mapping(address => uint256) private _listingIdByDapp;

    /// @notice Category => array of listing IDs
    mapping(string => uint256[]) private _listingsByCategory;

    /// @notice Featured listing IDs
    uint256[] private _featuredListings;

    /// @notice All active listing IDs
    uint256[] private _activeListingIds;

    /// @notice Incremental listing ID counter
    uint256 private _listingCount;

    /// @notice Platform fee basis points (e.g., 250 = 2.5%)
    uint256 public platformFeeBps;

    /// @notice Maximum basis points
    uint256 public constant MAX_BPS = 10000;

    /// @notice Maximum tags length
    uint256 public constant MAX_TAGS_LENGTH = 500;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a dApp is listed
    event AppListed(
        uint256 indexed listingId,
        address indexed dappAddress,
        address indexed seller,
        string title,
        string category,
        uint256 price,
        uint256 timestamp
    );

    /// @notice Emitted when a listing is updated
    event ListingUpdated(
        uint256 indexed listingId,
        string title,
        uint256 price,
        uint256 timestamp
    );

    /// @notice Emitted when a dApp is delisted
    event AppDelisted(
        uint256 indexed listingId,
        address indexed dappAddress,
        uint256 timestamp
    );

    /// @notice Emitted when a listing is featured or unfeatured
    event FeaturedUpdated(
        uint256 indexed listingId,
        bool isFeatured,
        uint256 featuredUntil,
        uint256 timestamp
    );

    /// @notice Emitted when platform fee is updated
    event PlatformFeeUpdated(uint256 oldFee, uint256 newFee, uint256 timestamp);

    /// @notice Emitted when a sale occurs
    event AppSold(
        uint256 indexed listingId,
        address indexed buyer,
        uint256 price,
        uint256 timestamp
    );

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyTitle();
    error ListingNotFound(uint256 listingId);
    error AlreadyListed(address dappAddress);
    error NotSeller(uint256 listingId);
    error ListingInactive(uint256 listingId);
    error TagsTooLong(uint256 length, uint256 max);
    error InvalidFee();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(uint256 feeBps) {
        _transferOwnership(msg.sender);
        if (feeBps > MAX_BPS) revert InvalidFee();
        platformFeeBps = feeBps;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the platform fee basis points
    /// @param newFeeBps The new fee in basis points
    function setPlatformFeeBps(uint256 newFeeBps) external onlyOwner {
        if (newFeeBps > MAX_BPS) revert InvalidFee();
        uint256 oldFee = platformFeeBps;
        platformFeeBps = newFeeBps;
        emit PlatformFeeUpdated(oldFee, newFeeBps, block.timestamp);
    }

    /// @notice Toggle featured status for a listing
    /// @param listingId The listing ID
    /// @param isFeatured Whether to feature
    /// @param duration Duration in seconds (0 for permanent if featuring)
    function setFeatured(uint256 listingId, bool isFeatured, uint256 duration) external onlyOwner {
        if (listingId == 0 || listingId > _listingCount) revert ListingNotFound(listingId);
        Listing storage listing = _listings[listingId];

        listing.isFeatured = isFeatured;
        listing.featuredUntil = isFeatured ? (duration > 0 ? block.timestamp + duration : type(uint256).max) : 0;

        if (isFeatured) {
            _featuredListings.push(listingId);
        } else {
            _removeFromArray(_featuredListings, listingId);
        }

        emit FeaturedUpdated(listingId, isFeatured, listing.featuredUntil, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice List a dApp on the marketplace
    /// @param dappAddress The dApp contract address
    /// @param title Listing title
    /// @param description Listing description
    /// @param category Category
    /// @param tags Comma-separated tags
    /// @param metadataURI URI to metadata
    /// @param price Price in wei (0 = free)
    /// @return listingId The new listing ID
    function listApp(
        address dappAddress,
        string calldata title,
        string calldata description,
        string calldata category,
        string calldata tags,
        string calldata metadataURI,
        uint256 price
    ) external nonReentrant returns (uint256 listingId) {
        if (dappAddress == address(0)) revert ZeroAddress();
        if (bytes(title).length == 0) revert EmptyTitle();
        if (_listingIdByDapp[dappAddress] != 0) revert AlreadyListed(dappAddress);
        if (bytes(tags).length > MAX_TAGS_LENGTH) revert TagsTooLong(bytes(tags).length, MAX_TAGS_LENGTH);

        _listingCount++;
        listingId = _listingCount;

        _listings[listingId] = Listing({
            id: listingId,
            dappAddress: dappAddress,
            seller: msg.sender,
            title: title,
            description: description,
            category: category,
            tags: tags,
            metadataURI: metadataURI,
            price: price,
            isActive: true,
            isFeatured: false,
            featuredUntil: 0,
            createdAt: block.timestamp,
            updatedAt: block.timestamp,
            totalSales: 0,
            totalRevenue: 0
        });

        _listingIdByDapp[dappAddress] = listingId;
        _listingsByCategory[category].push(listingId);
        _activeListingIds.push(listingId);

        emit AppListed(listingId, dappAddress, msg.sender, title, category, price, block.timestamp);
    }

    /// @notice Update an existing listing
    /// @param listingId The listing ID
    /// @param title New title
    /// @param description New description
    /// @param category New category
    /// @param tags New tags
    /// @param metadataURI New metadata URI
    /// @param price New price
    function updateListing(
        uint256 listingId,
        string calldata title,
        string calldata description,
        string calldata category,
        string calldata tags,
        string calldata metadataURI,
        uint256 price
    ) external nonReentrant {
        if (listingId == 0 || listingId > _listingCount) revert ListingNotFound(listingId);
        Listing storage listing = _listings[listingId];
        if (listing.seller != msg.sender && owner() != msg.sender) revert NotSeller(listingId);
        if (bytes(title).length == 0) revert EmptyTitle();
        if (bytes(tags).length > MAX_TAGS_LENGTH) revert TagsTooLong(bytes(tags).length, MAX_TAGS_LENGTH);

        listing.title = title;
        listing.description = description;
        listing.category = category;
        listing.tags = tags;
        listing.metadataURI = metadataURI;
        listing.price = price;
        listing.updatedAt = block.timestamp;

        emit ListingUpdated(listingId, title, price, block.timestamp);
    }

    /// @notice Delist a dApp from the marketplace
    /// @param listingId The listing ID to delist
    function delistApp(uint256 listingId) external nonReentrant {
        if (listingId == 0 || listingId > _listingCount) revert ListingNotFound(listingId);
        Listing storage listing = _listings[listingId];
        if (listing.seller != msg.sender && owner() != msg.sender) revert NotSeller(listingId);

        listing.isActive = false;
        listing.updatedAt = block.timestamp;

        _removeFromArray(_activeListingIds, listingId);

        emit AppDelisted(listingId, listing.dappAddress, block.timestamp);
    }

    /// @notice Buy/purchase a listed dApp
    /// @param listingId The listing ID
    function buyApp(uint256 listingId) external payable nonReentrant {
        if (listingId == 0 || listingId > _listingCount) revert ListingNotFound(listingId);
        Listing storage listing = _listings[listingId];
        if (!listing.isActive) revert ListingInactive(listingId);
        if (msg.value < listing.price) revert("INSUFFICIENT_PAYMENT");

        uint256 fee = (listing.price * platformFeeBps) / MAX_BPS;
        uint256 sellerProceeds = listing.price - fee;

        listing.totalSales++;
        listing.totalRevenue += listing.price;

        // Send fee to platform
        if (fee > 0) {
            (bool feeSuccess,) = payable(owner()).call{value: fee}("");
            require(feeSuccess, "FEE_TRANSFER_FAILED");
        }

        // Send proceeds to seller
        if (sellerProceeds > 0) {
            (bool sellerSuccess,) = payable(listing.seller).call{value: sellerProceeds}("");
            require(sellerSuccess, "SELLER_TRANSFER_FAILED");
        }

        // Refund excess payment
        uint256 excess = msg.value - listing.price;
        if (excess > 0) {
            (bool refundSuccess,) = payable(msg.sender).call{value: excess}("");
            require(refundSuccess, "REFUND_FAILED");
        }

        emit AppSold(listingId, msg.sender, listing.price, block.timestamp);
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Remove a value from an array
    function _removeFromArray(uint256[] storage arr, uint256 value) internal {
        uint256 len = arr.length;
        for (uint256 i = 0; i < len; i++) {
            if (arr[i] == value) {
                arr[i] = arr[len - 1];
                arr.pop();
                break;
            }
        }
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get listing by ID
    /// @param listingId The listing ID
    /// @return Listing struct
    function getListing(uint256 listingId) external view returns (Listing memory) {
        if (listingId == 0 || listingId > _listingCount) revert ListingNotFound(listingId);
        return _listings[listingId];
    }

    /// @notice Get listing by dApp address
    /// @param dappAddress The dApp address
    /// @return Listing struct
    function getListingByDapp(address dappAddress) external view returns (Listing memory) {
        uint256 listingId = _listingIdByDapp[dappAddress];
        if (listingId == 0) revert ListingNotFound(listingId);
        return _listings[listingId];
    }

    /// @notice Get total number of listings
    /// @return count The listing count
    function getListingCount() external view returns (uint256) {
        return _listingCount;
    }

    /// @notice Search apps by title or description (simple substring match)
    /// @param query The search query
    /// @param offset Starting index
    /// @param limit Max results
    /// @return listings Array of matching Listing structs
    function searchApps(
        string calldata query,
        uint256 offset,
        uint256 limit
    ) external view returns (Listing[] memory listings) {
        if (bytes(query).length == 0) {
            return getListings(offset, limit);
        }

        // Count matches
        uint256 matchCount = 0;
        bytes32 queryLower = _toLower(keccak256(bytes(query)));

        // We do a simple scan - in production you'd use an index
        for (uint256 i = 1; i <= _listingCount; i++) {
            if (_matchesQuery(_listings[i], query, queryLower)) {
                matchCount++;
            }
        }

        if (offset >= matchCount) return new Listing[](0);

        uint256 end = offset + limit;
        if (end > matchCount) end = matchCount;
        uint256 resultCount = end - offset;

        listings = new Listing[](resultCount);
        uint256 idx = 0;
        uint256 found = 0;
        for (uint256 i = 1; i <= _listingCount && found < end; i++) {
            if (_matchesQuery(_listings[i], query, queryLower)) {
                found++;
                if (found > offset) {
                    listings[idx] = _listings[i];
                    idx++;
                }
            }
        }
    }

    /// @notice Check if a listing matches a search query
    function _matchesQuery(Listing storage listing, string calldata query, bytes32 queryLower) internal view returns (bool) {
        // Simple substring check on title and description
        bytes32 titleLower = _toLower(keccak256(bytes(listing.title)));
        bytes32 descLower = _toLower(keccak256(bytes(listing.description)));

        // For simplicity, we check if the keccak of the query is contained
        // In production, you'd use a more sophisticated search
        if (titleLower == queryLower) return true;
        if (descLower == queryLower) return true;

        // Check tags
        if (keccak256(bytes(listing.tags)) == queryLower) return true;

        // Fallback: check if query is substring of title (approximate)
        string memory title = listing.title;
        if (bytes(title).length >= bytes(query).length) {
            return _contains(title, query);
        }

        return false;
    }

    /// @notice Simple substring check
    function _contains(string memory a, string calldata b) internal pure returns (bool) {
        bytes memory aBytes = bytes(a);
        bytes memory bBytes = bytes(b);
        if (bBytes.length > aBytes.length) return false;
        for (uint256 i = 0; i <= aBytes.length - bBytes.length; i++) {
            bool isMatch = true;
            for (uint256 j = 0; j < bBytes.length; j++) {
                if (aBytes[i + j] != bBytes[j]) {
                    isMatch = false;
                    break;
                }
            }
            if (isMatch) return true;
        }
        return false;
    }

    /// @notice Convert a hash to lowercase (simplified - just returns the hash)
    function _toLower(bytes32 input) internal pure returns (bytes32) {
        return input;
    }

    /// @notice Get all listings (paginated)
    /// @param offset Starting index
    /// @param limit Max results
    /// @return listings Array of Listing structs
    function getListings(uint256 offset, uint256 limit) public view returns (Listing[] memory listings) {
        if (offset >= _listingCount) return new Listing[](0);
        uint256 end = offset + limit;
        if (end > _listingCount) end = _listingCount;
        uint256 resultCount = end - offset;
        listings = new Listing[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            listings[i] = _listings[offset + i + 1];
        }
    }

    /// @notice Get listings by category
    /// @param category The category
    /// @return listings Array of Listing structs
    function getListingsByCategory(string calldata category) external view returns (Listing[] memory listings) {
        uint256[] storage ids = _listingsByCategory[category];
        uint256 len = ids.length;
        listings = new Listing[](len);
        for (uint256 i = 0; i < len; i++) {
            listings[i] = _listings[ids[i]];
        }
    }

    /// @notice Get active listings (paginated)
    /// @param offset Starting index
    /// @param limit Max results
    /// @return listings Array of active Listing structs
    function getActiveListings(uint256 offset, uint256 limit) external view returns (Listing[] memory listings) {
        uint256 len = _activeListingIds.length;
        if (offset >= len) return new Listing[](0);
        uint256 end = offset + limit;
        if (end > len) end = len;
        uint256 resultCount = end - offset;
        listings = new Listing[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            listings[i] = _listings[_activeListingIds[offset + i]];
        }
    }

    /// @notice Get featured listings
    /// @return listings Array of featured Listing structs
    function getFeaturedApps() external view returns (Listing[] memory listings) {
        // Filter out expired featured listings
        uint256 activeFeatured = 0;
        uint256 featuredLen = _featuredListings.length;
        for (uint256 i = 0; i < featuredLen; i++) {
            Listing storage l = _listings[_featuredListings[i]];
            if (l.isFeatured && (l.featuredUntil >= block.timestamp || l.featuredUntil == type(uint256).max)) {
                activeFeatured++;
            }
        }

        listings = new Listing[](activeFeatured);
        uint256 idx = 0;
        for (uint256 i = 0; i < featuredLen; i++) {
            Listing storage l = _listings[_featuredListings[i]];
            if (l.isFeatured && (l.featuredUntil >= block.timestamp || l.featuredUntil == type(uint256).max)) {
                listings[idx] = l;
                idx++;
            }
        }
    }

    /// @notice Get listings by seller
    /// @param seller The seller address
    /// @return listings Array of Listing structs
    function getListingsBySeller(address seller) external view returns (Listing[] memory listings) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _listingCount; i++) {
            if (_listings[i].seller == seller) count++;
        }
        listings = new Listing[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _listingCount; i++) {
            if (_listings[i].seller == seller) {
                listings[idx] = _listings[i];
                idx++;
            }
        }
    }
}

contracts/foundry/FoundryReferralRouter..content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryReferralRouter — Referral/Affiliate System for X3 Foundry
/// @notice Referral/affiliate system that maps users to referrers and tracks referral revenue
/// @dev Uses pull-over-push pattern for reward claims
contract FoundryReferralRouter is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Referral statistics for a referrer
    struct ReferralStats {
        uint256 totalReferrals;         // Total number of referred users
        uint256 activeReferrals;        // Number of active referred users
        uint256 totalRevenueGenerated;  // Total revenue generated by referrals (wei)
        uint256 totalRewardsClaimed;    // Total rewards claimed by referrer (wei)
        uint256 pendingRewards;         // Unclaimed rewards (wei)
        uint256 lastClaimTime;          // Timestamp of last claim
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice User address => referrer address
    mapping(address => address) public referrerOf;

    /// @notice Referrer address => ReferralStats
    mapping(address => ReferralStats) private _referralStats;

    /// @notice Whether a user has already set a referrer
    mapping(address => bool) private _hasReferrer;

    /// @notice List of all referrers
    address[] private _referrers;

    /// @notice Whether an address is tracked as a referrer
    mapping(address => bool) private _isReferrer;

    /// @notice Default referral reward basis points (e.g., 500 = 5%)
    uint256 public defaultRewardBps;

    /// @notice Maximum basis points
    uint256 public constant MAX_BPS = 10000;

    /// @notice Minimum referral reward basis points
    uint256 public constant MIN_REWARD_BPS = 100; // 1%

    /// @notice Maximum referral reward basis points
    uint256 public constant MAX_REWARD_BPS = 3000; // 30%

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a referrer is set for a user
    event ReferrerSet(
        address indexed user,
        address indexed referrer,
        uint256 timestamp
    );

    /// @notice Emitted when a referral is recorded (revenue generated)
    event ReferralRecorded(
        address indexed referrer,
        address indexed referredUser,
        uint256 revenueAmount,
        uint256 rewardAmount,
        uint256 timestamp
    );

    /// @notice Emitted when a referrer claims rewards
    event ReferralRewardsClaimed(
        address indexed referrer,
        uint256 amount,
        uint256 timestamp
    );

    /// @notice Emitted when default reward basis points are updated
    event DefaultRewardBpsUpdated(uint256 oldBps, uint256 newBps, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error SelfReferral();
    error ReferrerAlreadySet(address user);
    error ReferrerCannotBeZero();
    error InvalidRewardBps(uint256 bps);
    error NoRewardsToClaim();
    error TransferFailed();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(uint256 _defaultRewardBps) {
        _transferOwnership(msg.sender);
        if (_defaultRewardBps < MIN_REWARD_BPS || _defaultRewardBps > MAX_REWARD_BPS) {
            revert InvalidRewardBps(_defaultRewardBps);
        }
        defaultRewardBps = _defaultRewardBps;
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the default referral reward basis points
    /// @param newBps The new reward basis points
    function setDefaultRewardBps(uint256 newBps) external onlyOwner {
        if (newBps < MIN_REWARD_BPS || newBps > MAX_REWARD_BPS) {
            revert InvalidRewardBps(newBps);
        }
        uint256 oldBps = defaultRewardBps;
        defaultRewardBps = newBps;
        emit DefaultRewardBpsUpdated(oldBps, newBps, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Set a referrer for the caller
    /// @param referrer The referrer address
    function setReferrer(address referrer) external {
        if (referrer == address(0)) revert ZeroAddress();
        if (referrer == msg.sender) revert SelfReferral();
        if (_hasReferrer[msg.sender]) revert ReferrerAlreadySet(msg.sender);

        referrerOf[msg.sender] = referrer;
        _hasReferrer[msg.sender] = true;

        ReferralStats storage stats = _referralStats[referrer];
        stats.totalReferrals++;
        stats.activeReferrals++;

        if (!_isReferrer[referrer]) {
            _isReferrer[referrer] = true;
            _referrers.push(referrer);
        }

        emit ReferrerSet(msg.sender, referrer, block.timestamp);
    }

    /// @notice Record a referral event (revenue generated by a referred user)
    /// @param referredUser The user who generated revenue
    /// @param revenueAmount The revenue amount in wei
    function recordReferral(address referredUser, uint256 revenueAmount) external payable nonReentrant {
        if (referredUser == address(0)) revert ZeroAddress();
        if (revenueAmount == 0 && msg.value == 0) revert("NO_VALUE");

        address referrer = referrerOf[referredUser];
        if (referrer == address(0)) revert ReferrerCannotBeZero();

        uint256 actualAmount = revenueAmount > 0 ? revenueAmount : msg.value;
        uint256 rewardAmount = (actualAmount * defaultRewardBps) / MAX_BPS;

        ReferralStats storage stats = _referralStats[referrer];
        stats.totalRevenueGenerated += actualAmount;
        stats.pendingRewards += rewardAmount;

        emit ReferralRecorded(referrer, referredUser, actualAmount, rewardAmount, block.timestamp);
    }

    /// @notice Claim pending referral rewards (pull-over-push)
    /// @param amount The amount to claim
    function claimReferralRewards(uint256 amount) external nonReentrant {
        ReferralStats storage stats = _referralStats[msg.sender];
        if (stats.pendingRewards == 0) revert NoRewardsToClaim();
        if (amount > stats.pendingRewards) amount = stats.pendingRewards;

        stats.pendingRewards -= amount;
        stats.totalRewardsClaimed += amount;
        stats.lastClaimTime = block.timestamp;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit ReferralRewardsClaimed(msg.sender, amount, block.timestamp);
    }

    /// @notice Claim all pending referral rewards
    function claimAllReferralRewards() external nonReentrant {
        ReferralStats storage stats = _referralStats[msg.sender];
        uint256 amount = stats.pendingRewards;
        if (amount == 0) revert NoRewardsToClaim();

        stats.pendingRewards = 0;
        stats.totalRewardsClaimed += amount;
        stats.lastClaimTime = block.timestamp;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit ReferralRewardsClaimed(msg.sender, amount, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get the referrer for a user
    /// @param user The user address
    /// @return The referrer address (address(0) if none)
    function getReferrer(address user) external view returns (address) {
        return referrerOf[user];
    }

    /// @notice Get referral stats for a referrer
    /// @param referrer The referrer address
    /// @return ReferralStats struct
    function getReferralStats(address referrer) external view returns (ReferralStats memory) {
        return _referralStats[referrer];
    }

    /// @notice Check if a user has a referrer set
    /// @param user The user address
    /// @return True if referrer is set
    function hasReferrer(address user) external view returns (bool) {
        return _hasReferrer[user];
    }

    /// @notice Get total number of referrers
    /// @return count The referrer count
    function getReferrerCount() external view returns (uint256) {
        return _referrers.length;
    }

    /// @notice Get referrer at index
    /// @param index The index
    /// @return referrer The referrer address
    function getReferrerAt(uint256 index) external view returns (address) {
        return _referrers[index];
    }

    /// @notice Calculate the reward amount for a given revenue
    /// @param revenueAmount The revenue amount
    /// @return rewardAmount The calculated reward
    function calculateReward(uint256 revenueAmount) external view returns (uint256) {
        return (revenueAmount * defaultRewardBps) / MAX_BPS;
    }
}

contracts/foundry/FoundryRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title FoundryRegistry — Main dApp Registry for X3 Foundry
/// @notice Stores all deployed dApps with full metadata on-chain
/// @dev Admin functions are restricted to the contract owner
contract FoundryRegistry is Ownable, ReentrancyGuard {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Full metadata for a registered dApp
    struct DappInfo {
        address dappAddress;
        address creator;
        string name;
        string description;
        string category;
        string version;
        string metadataURI;
        bool isActive;
        uint256 registeredAt;
        uint256 updatedAt;
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Incremental ID counter for dApps
    uint256 private _dappCount;

    /// @notice dApp ID => DappInfo
    mapping(uint256 => DappInfo) private _dapps;

    /// @notice dApp address => dApp ID (for reverse lookup)
    mapping(address => uint256) private _dappIdByAddress;

    /// @notice dApp address => whether it's registered
    mapping(address => bool) private _isRegistered;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a new dApp is registered
    event DappRegistered(
        uint256 indexed dappId,
        address indexed dappAddress,
        address indexed creator,
        string name,
        string category,
        uint256 timestamp
    );

    /// @notice Emitted when a dApp's metadata is updated
    event DappUpdated(
        uint256 indexed dappId,
        address indexed dappAddress,
        string name,
        string category,
        uint256 timestamp
    );

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyName();
    error DappAlreadyRegistered(address dappAddress);
    error DappNotRegistered(uint256 dappId);
    error DappNotActive(uint256 dappId);
    error NotDappCreator(uint256 dappId);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Admin / Write Functions ──────────────────────────────────────────────

    /// @notice Register a new dApp in the registry
    /// @param dappAddress The deployed contract address of the dApp
    /// @param name The name of the dApp
    /// @param description A short description of the dApp
    /// @param category The category (e.g., "DeFi", "Gaming", "Social")
    /// @param version The version string (e.g., "1.0.0")
    /// @param metadataURI URI pointing to off-chain metadata (JSON)
    /// @return dappId The assigned dApp ID
    function registerDapp(
        address dappAddress,
        string calldata name,
        string calldata description,
        string calldata category,
        string calldata version,
        string calldata metadataURI
    ) external nonReentrant returns (uint256 dappId) {
        if (dappAddress == address(0)) revert ZeroAddress();
        if (bytes(name).length == 0) revert EmptyName();
        if (_isRegistered[dappAddress]) revert DappAlreadyRegistered(dappAddress);

        _dappCount++;
        dappId = _dappCount;

        _dapps[dappId] = DappInfo({
            dappAddress: dappAddress,
            creator: msg.sender,
            name: name,
            description: description,
            category: category,
            version: version,
            metadataURI: metadataURI,
            isActive: true,
            registeredAt: block.timestamp,
            updatedAt: block.timestamp
        });

        _dappIdByAddress[dappAddress] = dappId;
        _isRegistered[dappAddress] = true;

        emit DappRegistered(dappId, dappAddress, msg.sender, name, category, block.timestamp);
    }

    /// @notice Update an existing dApp's metadata
    /// @param dappId The ID of the dApp to update
    /// @param name New name
    /// @param description New description
    /// @param category New category
    /// @param version New version
    /// @param metadataURI New metadata URI
    /// @param isActive Whether the dApp is active
    function updateDapp(
        uint256 dappId,
        string calldata name,
        string calldata description,
        string calldata category,
        string calldata version,
        string calldata metadataURI,
        bool isActive
    ) external nonReentrant {
        if (dappId == 0 || dappId > _dappCount) revert DappNotRegistered(dappId);
        DappInfo storage dapp = _dapps[dappId];
        if (dapp.creator != msg.sender && owner() != msg.sender) revert NotDappCreator(dappId);
        if (bytes(name).length == 0) revert EmptyName();

        dapp.name = name;
        dapp.description = description;
        dapp.category = category;
        dapp.version = version;
        dapp.metadataURI = metadataURI;
        dapp.isActive = isActive;
        dapp.updatedAt = block.timestamp;

        emit DappUpdated(dappId, dapp.dappAddress, name, category, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get full dApp info by ID
    /// @param dappId The dApp ID
    /// @return DappInfo struct
    function getDapp(uint256 dappId) external view returns (DappInfo memory) {
        if (dappId == 0 || dappId > _dappCount) revert DappNotRegistered(dappId);
        return _dapps[dappId];
    }

    /// @notice Get dApp ID by contract address
    /// @param dappAddress The dApp contract address
    /// @return dappId The dApp ID (0 if not registered)
    function getDappIdByAddress(address dappAddress) external view returns (uint256) {
        return _dappIdByAddress[dappAddress];
    }

    /// @notice Total number of registered dApps
    /// @return count The dApp count
    function getDappCount() external view returns (uint256) {
        return _dappCount;
    }

    /// @notice Check if a dApp address is registered
    /// @param dappAddress The dApp contract address
    /// @return True if registered
    function isDappRegistered(address dappAddress) external view returns (bool) {
        return _isRegistered[dappAddress];
    }

    /// @notice Get a paginated list of all registered dApps
    /// @param offset Starting index (0-based)
    /// @param limit Maximum number of results
    /// @return dapps Array of DappInfo
    function getDapps(uint256 offset, uint256 limit) external view returns (DappInfo[] memory dapps) {
        if (offset >= _dappCount) return new DappInfo[](0);
        uint256 end = offset + limit;
        if (end > _dappCount) end = _dappCount;
        uint256 resultCount = end - offset;
        dapps = new DappInfo[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            dapps[i] = _dapps[offset + i + 1];
        }
    }

    /// @notice Get all dApps by a specific creator
    /// @param creator The creator address
    /// @return dapps Array of DappInfo
    function getDappsByCreator(address creator) external view returns (DappInfo[] memory dapps) {
        uint256 count = 0;
        for (uint256 i = 1; i <= _dappCount; i++) {
            if (_dapps[i].creator == creator) count++;
        }
        dapps = new DappInfo[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _dappCount; i++) {
            if (_dapps[i].creator == creator) {
                dapps[idx] = _dapps[i];
                idx++;
            }
        }
    }
}

contracts/foundry/FoundryRevenueRouter.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title FoundryRevenueRouter — Revenue Routing for X3 Foundry
/// @notice Routes revenue from dApps to the treasury split destinations
/// @dev Uses ReentrancyGuard for safety and Ownable for admin functions
contract FoundryRevenueRouter is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Treasury split configuration
    struct TreasurySplit {
        uint256 protocolTreasuryBps;   // Basis points for protocol treasury
        uint256 gpuSwarmBps;           // Basis points for GPU Swarm
        uint256 devVaultBps;           // Basis points for Developer Vault
        uint256 maintenanceBps;        // Basis points for Maintenance
        uint256 liquidityBps;          // Basis points for Liquidity
        uint256 grantsBps;             // Basis points for Grants
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Maximum basis points (100%)
    uint256 public constant MAX_BPS = 10000;

    /// @notice Default protocol treasury share (40%)
    uint256 public constant DEFAULT_PROTOCOL_TREASURY_BPS = 4000;
    /// @notice Default GPU swarm share (20%)
    uint256 public constant DEFAULT_GPU_SWARM_BPS = 2000;
    /// @notice Default dev vault share (15%)
    uint256 public constant DEFAULT_DEV_VAULT_BPS = 1500;
    /// @notice Default maintenance share (10%)
    uint256 public constant DEFAULT_MAINTENANCE_BPS = 1000;
    /// @notice Default liquidity share (10%)
    uint256 public constant DEFAULT_LIQUIDITY_BPS = 1000;
    /// @notice Default grants share (5%)
    uint256 public constant DEFAULT_GRANTS_BPS = 500;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Current treasury split configuration
    TreasurySplit private _treasurySplit;

    /// @notice Protocol treasury address
    address public protocolTreasury;

    /// @notice GPU Swarm address
    address public gpuSwarm;

    /// @notice Developer Vault address
    address public devVault;

    /// @notice Maintenance address
    address public maintenance;

    /// @notice Liquidity address
    address public liquidity;

    /// @notice Grants address
    address public grants;

    /// @notice Revenue accumulated per dApp (in wei / token units)
    mapping(address => uint256) public revenueByApp;

    /// @notice Revenue accumulated per creator
    mapping(address => uint256) public revenueByCreator;

    /// @notice Total revenue routed all-time
    uint256 public totalRevenue;

    /// @notice dApp => creator mapping
    mapping(address => address) public dappCreator;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when revenue is routed
    event RevenueRouted(
        address indexed dapp,
        address indexed token,
        uint256 amount,
        uint256 timestamp
    );

    /// @notice Emitted when treasury split is updated
    event TreasurySplitUpdated(
        uint256 protocolTreasuryBps,
        uint256 gpuSwarmBps,
        uint256 devVaultBps,
        uint256 maintenanceBps,
        uint256 liquidityBps,
        uint256 grantsBps,
        uint256 timestamp
    );

    /// @notice Emitted when a destination address is updated
    event DestinationUpdated(string indexed name, address indexed newAddress);

    // ── Errors ───────────────────────────────────────────────────────────────

    error InvalidSplit();
    error ZeroAddress();
    error ZeroAmount();
    error NoCreatorSet();

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(
        address _protocolTreasury,
        address _gpuSwarm,
        address _devVault,
        address _maintenance,
        address _liquidity,
        address _grants
    ) {
        _transferOwnership(msg.sender);
        if (_protocolTreasury == address(0)) revert ZeroAddress();
        if (_gpuSwarm == address(0)) revert ZeroAddress();
        if (_devVault == address(0)) revert ZeroAddress();
        if (_maintenance == address(0)) revert ZeroAddress();
        if (_liquidity == address(0)) revert ZeroAddress();
        if (_grants == address(0)) revert ZeroAddress();

        protocolTreasury = _protocolTreasury;
        gpuSwarm = _gpuSwarm;
        devVault = _devVault;
        maintenance = _maintenance;
        liquidity = _liquidity;
        grants = _grants;

        _treasurySplit = TreasurySplit({
            protocolTreasuryBps: DEFAULT_PROTOCOL_TREASURY_BPS,
            gpuSwarmBps: DEFAULT_GPU_SWARM_BPS,
            devVaultBps: DEFAULT_DEV_VAULT_BPS,
            maintenanceBps: DEFAULT_MAINTENANCE_BPS,
            liquidityBps: DEFAULT_LIQUIDITY_BPS,
            grantsBps: DEFAULT_GRANTS_BPS
        });
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the treasury split percentages (in basis points)
    /// @param split The new TreasurySplit configuration
    function setTreasurySplit(TreasurySplit calldata split) external onlyOwner {
        uint256 total = split.protocolTreasuryBps + split.gpuSwarmBps + split.devVaultBps
            + split.maintenanceBps + split.liquidityBps + split.grantsBps;
        if (total != MAX_BPS) revert InvalidSplit();

        _treasurySplit = split;

        emit TreasurySplitUpdated(
            split.protocolTreasuryBps,
            split.gpuSwarmBps,
            split.devVaultBps,
            split.maintenanceBps,
            split.liquidityBps,
            split.grantsBps,
            block.timestamp
        );
    }

    /// @notice Set a destination address for a named treasury component
    function setDestination(string calldata name, address newAddress) external onlyOwner {
        if (newAddress == address(0)) revert ZeroAddress();

        if (keccak256(bytes(name)) == keccak256(bytes("protocolTreasury"))) {
            protocolTreasury = newAddress;
        } else if (keccak256(bytes(name)) == keccak256(bytes("gpuSwarm"))) {
            gpuSwarm = newAddress;
        } else if (keccak256(bytes(name)) == keccak256(bytes("devVault"))) {
            devVault = newAddress;
        } else if (keccak256(bytes(name)) == keccak256(bytes("maintenance"))) {
            maintenance = newAddress;
        } else if (keccak256(bytes(name)) == keccak256(bytes("liquidity"))) {
            liquidity = newAddress;
        } else if (keccak256(bytes(name)) == keccak256(bytes("grants"))) {
            grants = newAddress;
        } else {
            revert("INVALID_DESTINATION");
        }

        emit DestinationUpdated(name, newAddress);
    }

    /// @notice Set the creator for a dApp (for revenue tracking)
    function setDappCreator(address dapp, address creator) external onlyOwner {
        if (dapp == address(0) || creator == address(0)) revert ZeroAddress();
        dappCreator[dapp] = creator;
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Route incoming revenue (native currency) according to the treasury split
    /// @param dapp The dApp address generating the revenue
    /// @param creator The creator address to credit
    function routeRevenue(address dapp, address creator) external payable nonReentrant {
        if (msg.value == 0) revert ZeroAmount();
        if (creator == address(0)) revert ZeroAddress();

        uint256 amount = msg.value;

        // Track revenue
        revenueByApp[dapp] += amount;
        revenueByCreator[creator] += amount;
        totalRevenue += amount;

        // Split and forward
        _splitAndForward(amount);

        emit RevenueRouted(dapp, address(0), amount, block.timestamp);
    }

    /// @notice Route incoming ERC20 revenue according to the treasury split
    /// @param dapp The dApp address generating the revenue
    /// @param creator The creator address to credit
    /// @param token The ERC20 token address
    /// @param amount The amount of tokens
    function routeRevenueToken(
        address dapp,
        address creator,
        IERC20 token,
        uint256 amount
    ) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (creator == address(0)) revert ZeroAddress();
        if (address(token) == address(0)) revert ZeroAddress();

        // Transfer tokens from sender
        token.safeTransferFrom(msg.sender, address(this), amount);

        // Track revenue
        revenueByApp[dapp] += amount;
        revenueByCreator[creator] += amount;
        totalRevenue += amount;

        // Split and forward
        _splitAndForwardToken(token, amount);

        emit RevenueRouted(dapp, address(token), amount, block.timestamp);
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Split native currency and forward to destinations
    function _splitAndForward(uint256 amount) internal {
        TreasurySplit memory split = _treasurySplit;

        _sendNative(protocolTreasury, (amount * split.protocolTreasuryBps) / MAX_BPS);
        _sendNative(gpuSwarm, (amount * split.gpuSwarmBps) / MAX_BPS);
        _sendNative(devVault, (amount * split.devVaultBps) / MAX_BPS);
        _sendNative(maintenance, (amount * split.maintenanceBps) / MAX_BPS);
        _sendNative(liquidity, (amount * split.liquidityBps) / MAX_BPS);
        _sendNative(grants, (amount * split.grantsBps) / MAX_BPS);
    }

    /// @notice Split ERC20 tokens and forward to destinations
    function _splitAndForwardToken(IERC20 token, uint256 amount) internal {
        TreasurySplit memory split = _treasurySplit;

        _sendToken(token, protocolTreasury, (amount * split.protocolTreasuryBps) / MAX_BPS);
        _sendToken(token, gpuSwarm, (amount * split.gpuSwarmBps) / MAX_BPS);
        _sendToken(token, devVault, (amount * split.devVaultBps) / MAX_BPS);
        _sendToken(token, maintenance, (amount * split.maintenanceBps) / MAX_BPS);
        _sendToken(token, liquidity, (amount * split.liquidityBps) / MAX_BPS);
        _sendToken(token, grants, (amount * split.grantsBps) / MAX_BPS);
    }

    /// @notice Send native currency to an address
    function _sendNative(address to, uint256 amount) internal {
        if (amount > 0) {
            (bool success,) = payable(to).call{value: amount}("");
            require(success, "TRANSFER_FAILED");
        }
    }

    /// @notice Send ERC20 tokens to an address
    function _sendToken(IERC20 token, address to, uint256 amount) internal {
        if (amount > 0) {
            token.safeTransfer(to, amount);
        }
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get the current treasury split configuration
    /// @return TreasurySplit struct
    function getTreasurySplit() external view returns (TreasurySplit memory) {
        return _treasurySplit;
    }

    /// @notice Get total revenue routed for a specific dApp
    /// @param dapp The dApp address
    /// @return Total revenue in wei/token units
    function getRevenueByApp(address dapp) external view returns (uint256) {
        return revenueByApp[dapp];
    }

    /// @notice Get total revenue attributed to a specific creator
    /// @param creator The creator address
    /// @return Total revenue in wei/token units
    function getRevenueByCreator(address creator) external view returns (uint256) {
        return revenueByCreator[creator];
    }

    /// @notice Get total revenue routed all-time
    /// @return Total revenue in wei/token units
    function getTotalRevenue() external view returns (uint256) {
        return totalRevenue;
    }
}

contracts/foundry/FoundrySubscriptionMan.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title FoundrySubscriptionManager — Subscription Manager for X3 Foundry
/// @notice Subscription management for SaaS dApps with billing cycle tracking
/// @dev Handles subscriptions, renewals, cancellations, and billing cycles
contract FoundrySubscriptionManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Represents a subscription
    struct Subscription {
        address subscriber;
        address dapp;
        uint256 price;                  // Price per billing cycle (in wei or token units)
        uint256 billingPeriod;          // Billing period in seconds (e.g., 30 days)
        uint256 startTime;              // When the subscription started
        uint256 endTime;                // When the current billing period ends
        uint256 lastPaymentTime;        // Timestamp of last payment
        uint256 totalPaid;              // Total amount paid all-time
        bool isActive;                  // Whether the subscription is active
        bool autoRenew;                 // Whether auto-renewal is enabled
        address paymentToken;           // address(0) for native, otherwise ERC20
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Subscription ID => Subscription
    mapping(uint256 => Subscription) private _subscriptions;

    /// @notice Subscriber address => dApp address => subscription ID
    mapping(address => mapping(address => uint256)) private _subscriptionId;

    /// @notice dApp address => default subscription price
    mapping(address => uint256) public defaultPrices;

    /// @notice dApp address => default billing period
    mapping(address => uint256) public defaultBillingPeriods;

    /// @notice dApp address => subscriber count
    mapping(address => uint256) public subscriberCount;

    /// @notice dApp address => total revenue from subscriptions
    mapping(address => uint256) public dappSubscriptionRevenue;

    /// @notice Incremental subscription ID counter
    uint256 private _subscriptionCounter;

    /// @notice Total active subscriptions
    uint256 public totalActiveSubscriptions;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a user subscribes to a dApp
    event Subscribed(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        address indexed dapp,
        uint256 price,
        uint256 billingPeriod,
        uint256 startTime,
        uint256 endTime
    );

    /// @notice Emitted when a subscription is cancelled
    event Cancelled(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        address indexed dapp,
        uint256 timestamp
    );

    /// @notice Emitted when a subscription is renewed
    event Renewed(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        address indexed dapp,
        uint256 amount,
        uint256 newEndTime
    );

    /// @notice Emitted when a dApp's default subscription price is set
    event SubscriptionPriceSet(
        address indexed dapp,
        uint256 price,
        uint256 billingPeriod,
        uint256 timestamp
    );

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroPrice();
    error ZeroBillingPeriod();
    error AlreadySubscribed(address subscriber, address dapp);
    error NotSubscribed(address subscriber, address dapp);
    error SubscriptionInactive(uint256 subscriptionId);
    error SubscriptionExpired(uint256 subscriptionId);
    error TransferFailed();
    error InsufficientPayment(uint256 required, uint256 provided);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the default subscription price and billing period for a dApp
    /// @param dapp The dApp address
    /// @param price The price per billing cycle
    /// @param billingPeriod The billing period in seconds
    function setSubscriptionPrice(
        address dapp,
        uint256 price,
        uint256 billingPeriod
    ) external onlyOwner {
        if (dapp == address(0)) revert ZeroAddress();
        if (price == 0) revert ZeroPrice();
        if (billingPeriod == 0) revert ZeroBillingPeriod();

        defaultPrices[dapp] = price;
        defaultBillingPeriods[dapp] = billingPeriod;

        emit SubscriptionPriceSet(dapp, price, billingPeriod, block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Subscribe to a dApp (pay with native currency)
    /// @param dapp The dApp address to subscribe to
    /// @param billingPeriod The billing period in seconds (0 to use default)
    /// @param autoRenew Whether to auto-renew
    /// @return subscriptionId The new subscription ID
    function subscribe(
        address dapp,
        uint256 billingPeriod,
        bool autoRenew
    ) external payable nonReentrant returns (uint256 subscriptionId) {
        if (dapp == address(0)) revert ZeroAddress();
        if (_subscriptionId[msg.sender][dapp] != 0) {
            revert AlreadySubscribed(msg.sender, dapp);
        }

        uint256 price = defaultPrices[dapp];
        if (price == 0) revert ZeroPrice();

        if (msg.value < price) revert InsufficientPayment(price, msg.value);

        uint256 period = billingPeriod > 0 ? billingPeriod : defaultBillingPeriods[dapp];
        if (period == 0) revert ZeroBillingPeriod();

        _subscriptionCounter++;
        subscriptionId = _subscriptionCounter;

        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + period;

        _subscriptions[subscriptionId] = Subscription({
            subscriber: msg.sender,
            dapp: dapp,
            price: price,
            billingPeriod: period,
            startTime: startTime,
            endTime: endTime,
            lastPaymentTime: startTime,
            totalPaid: price,
            isActive: true,
            autoRenew: autoRenew,
            paymentToken: address(0)
        });

        _subscriptionId[msg.sender][dapp] = subscriptionId;
        subscriberCount[dapp]++;
        totalActiveSubscriptions++;
        dappSubscriptionRevenue[dapp] += price;

        // Forward payment to dApp
        (bool success,) = payable(dapp).call{value: price}("");
        if (!success) revert TransferFailed();

        // Refund excess payment
        uint256 excess = msg.value - price;
        if (excess > 0) {
            (bool refundSuccess,) = payable(msg.sender).call{value: excess}("");
            require(refundSuccess, "REFUND_FAILED");
        }

        emit Subscribed(subscriptionId, msg.sender, dapp, price, period, startTime, endTime);
    }

    /// @notice Subscribe to a dApp using ERC20 tokens
    /// @param dapp The dApp address
    /// @param token The ERC20 token address
    /// @param billingPeriod The billing period in seconds
    /// @param autoRenew Whether to auto-renew
    /// @return subscriptionId The new subscription ID
    function subscribeWithToken(
        address dapp,
        IERC20 token,
        uint256 billingPeriod,
        bool autoRenew
    ) external nonReentrant returns (uint256 subscriptionId) {
        if (dapp == address(0)) revert ZeroAddress();
        if (address(token) == address(0)) revert ZeroAddress();
        if (_subscriptionId[msg.sender][dapp] != 0) {
            revert AlreadySubscribed(msg.sender, dapp);
        }

        uint256 price = defaultPrices[dapp];
        if (price == 0) revert ZeroPrice();

        uint256 period = billingPeriod > 0 ? billingPeriod : defaultBillingPeriods[dapp];
        if (period == 0) revert ZeroBillingPeriod();

        token.safeTransferFrom(msg.sender, address(this), price);

        _subscriptionCounter++;
        subscriptionId = _subscriptionCounter;

        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + period;

        _subscriptions[subscriptionId] = Subscription({
            subscriber: msg.sender,
            dapp: dapp,
            price: price,
            billingPeriod: period,
            startTime: startTime,
            endTime: endTime,
            lastPaymentTime: startTime,
            totalPaid: price,
            isActive: true,
            autoRenew: autoRenew,
            paymentToken: address(token)
        });

        _subscriptionId[msg.sender][dapp] = subscriptionId;
        subscriberCount[dapp]++;
        totalActiveSubscriptions++;
        dappSubscriptionRevenue[dapp] += price;

        // Forward tokens to dApp
        token.safeTransfer(dapp, price);

        emit Subscribed(subscriptionId, msg.sender, dapp, price, period, startTime, endTime);
    }

    /// @notice Cancel an active subscription
    /// @param subscriptionId The subscription ID to cancel
    function cancelSubscription(uint256 subscriptionId) external nonReentrant {
        Subscription storage sub = _subscriptions[subscriptionId];
        if (sub.subscriber != msg.sender) revert NotSubscribed(msg.sender, sub.dapp);
        if (!sub.isActive) revert SubscriptionInactive(subscriptionId);

        sub.isActive = false;
        sub.autoRenew = false;
        subscriberCount[sub.dapp]--;
        totalActiveSubscriptions--;

        emit Cancelled(subscriptionId, msg.sender, sub.dapp, block.timestamp);
    }

    /// @notice Renew a subscription (pay with native currency)
    /// @param subscriptionId The subscription ID to renew
    function renewSubscription(uint256 subscriptionId) external payable nonReentrant {
        Subscription storage sub = _subscriptions[subscriptionId];
        if (sub.subscriber != msg.sender) revert NotSubscribed(msg.sender, sub.dapp);
        if (!sub.isActive) revert SubscriptionInactive(subscriptionId);

        if (block.timestamp > sub.endTime) {
            // Subscription expired, treat as new period
            sub.startTime = block.timestamp;
        }

        if (msg.value < sub.price) revert InsufficientPayment(sub.price, msg.value);

        sub.endTime = block.timestamp + sub.billingPeriod;
        sub.lastPaymentTime = block.timestamp;
        sub.totalPaid += sub.price;
        dappSubscriptionRevenue[sub.dapp] += sub.price;

        // Forward payment to dApp
        (bool success,) = payable(sub.dapp).call{value: sub.price}("");
        if (!success) revert TransferFailed();

        // Refund excess
        uint256 excess = msg.value - sub.price;
        if (excess > 0) {
            (bool refundSuccess,) = payable(msg.sender).call{value: excess}("");
            require(refundSuccess, "REFUND_FAILED");
        }

        emit Renewed(subscriptionId, msg.sender, sub.dapp, sub.price, sub.endTime);
    }

    /// @notice Renew a subscription using ERC20 tokens
    /// @param subscriptionId The subscription ID to renew
    /// @param token The ERC20 token address
    function renewSubscriptionWithToken(uint256 subscriptionId, IERC20 token) external nonReentrant {
        Subscription storage sub = _subscriptions[subscriptionId];
        if (sub.subscriber != msg.sender) revert NotSubscribed(msg.sender, sub.dapp);
        if (!sub.isActive) revert SubscriptionInactive(subscriptionId);
        if (address(token) != sub.paymentToken) revert("WRONG_TOKEN");

        if (block.timestamp > sub.endTime) {
            sub.startTime = block.timestamp;
        }

        token.safeTransferFrom(msg.sender, address(this), sub.price);

        sub.endTime = block.timestamp + sub.billingPeriod;
        sub.lastPaymentTime = block.timestamp;
        sub.totalPaid += sub.price;
        dappSubscriptionRevenue[sub.dapp] += sub.price;

        token.safeTransfer(sub.dapp, sub.price);

        emit Renewed(subscriptionId, msg.sender, sub.dapp, sub.price, sub.endTime);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get subscription details by ID
    /// @param subscriptionId The subscription ID
    /// @return Subscription struct
    function getSubscription(uint256 subscriptionId) external view returns (Subscription memory) {
        return _subscriptions[subscriptionId];
    }

    /// @notice Get subscription ID for a subscriber-dApp pair
    /// @param subscriber The subscriber address
    /// @param dapp The dApp address
    /// @return subscriptionId The subscription ID (0 if none)
    function getSubscriptionId(address subscriber, address dapp) external view returns (uint256) {
        return _subscriptionId[subscriber][dapp];
    }

    /// @notice Get subscription for a subscriber-dApp pair
    /// @param subscriber The subscriber address
    /// @param dapp The dApp address
    /// @return Subscription struct
    function getSubscriptionByUserAndDapp(address subscriber, address dapp) external view returns (Subscription memory) {
        uint256 sid = _subscriptionId[subscriber][dapp];
        if (sid == 0) revert NotSubscribed(subscriber, dapp);
        return _subscriptions[sid];
    }

    /// @notice Get the number of active subscribers for a dApp
    /// @param dapp The dApp address
    /// @return count The subscriber count
    function getSubscriberCount(address dapp) external view returns (uint256) {
        return subscriberCount[dapp];
    }

    /// @notice Check if a subscription is expired
    /// @param subscriptionId The subscription ID
    /// @return True if expired
    function isExpired(uint256 subscriptionId) external view returns (bool) {
        return block.timestamp > _subscriptions[subscriptionId].endTime;
    }

    /// @notice Get total subscription revenue for a dApp
    /// @param dapp The dApp address
    /// @return revenue Total revenue
    function getDappRevenue(address dapp) external view returns (uint256) {
        return dappSubscriptionRevenue[dapp];
    }

    /// @notice Get total number of subscriptions created
    /// @return count Total subscriptions
    function getTotalSubscriptions() external view returns (uint256) {
        return _subscriptionCounter;
    }
}

contracts/foundry/FoundryTemplateRegistr.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title FoundryTemplateRegistry — dApp Template Registry for X3 Foundry
/// @notice Registry for dApp templates that can be used to deploy new dApps
/// @dev Stores template metadata and supports categorization
contract FoundryTemplateRegistry is Ownable {
    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice Full metadata for a dApp template
    struct Template {
        uint256 id;
        address author;
        string name;
        string description;
        string category;
        string version;
        string metadataURI;
        bytes32 bytecodeHash;       // keccak256 of the init code
        address templateAddress;    // Reference implementation address
        bool isActive;
        bool isDeprecated;
        uint256 createdAt;
        uint256 updatedAt;
    }

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Incremental ID counter
    uint256 private _templateCount;

    /// @notice Template ID => Template
    mapping(uint256 => Template) private _templates;

    /// @notice Template name => ID (for uniqueness check)
    mapping(bytes32 => uint256) private _templateIdByName;

    /// @notice Category => array of template IDs
    mapping(string => uint256[]) private _templatesByCategory;

    /// @notice Active template IDs
    uint256[] private _activeTemplateIds;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when a new template is registered
    event TemplateRegistered(
        uint256 indexed templateId,
        address indexed author,
        string name,
        string category,
        uint256 timestamp
    );

    /// @notice Emitted when a template is updated
    event TemplateUpdated(
        uint256 indexed templateId,
        string name,
        string version,
        uint256 timestamp
    );

    /// @notice Emitted when a template is deprecated
    event TemplateDeprecated(uint256 indexed templateId, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error EmptyName();
    error TemplateNotFound(uint256 templateId);
    error TemplateAlreadyExists(string name);
    error TemplateDeprecatedError(uint256 templateId);
    error NotTemplateAuthor(uint256 templateId);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Admin / Write Functions ──────────────────────────────────────────────

    /// @notice Register a new dApp template
    /// @param name Template name (must be unique)
    /// @param description Short description
    /// @param category Category (e.g., "DeFi", "NFT", "Gaming")
    /// @param version Version string
    /// @param metadataURI URI to off-chain metadata
    /// @param bytecodeHash keccak256 hash of the init code
    /// @param templateAddress Reference implementation address
    /// @return templateId The assigned template ID
    function registerTemplate(
        string calldata name,
        string calldata description,
        string calldata category,
        string calldata version,
        string calldata metadataURI,
        bytes32 bytecodeHash,
        address templateAddress
    ) external returns (uint256 templateId) {
        if (bytes(name).length == 0) revert EmptyName();

        bytes32 nameHash = keccak256(bytes(name));
        if (_templateIdByName[nameHash] != 0) revert TemplateAlreadyExists(name);

        _templateCount++;
        templateId = _templateCount;

        Template storage tmpl = _templates[templateId];
        tmpl.id = templateId;
        tmpl.author = msg.sender;
        tmpl.name = name;
        tmpl.description = description;
        tmpl.category = category;
        tmpl.version = version;
        tmpl.metadataURI = metadataURI;
        tmpl.bytecodeHash = bytecodeHash;
        tmpl.templateAddress = templateAddress;
        tmpl.isActive = true;
        tmpl.isDeprecated = false;
        tmpl.createdAt = block.timestamp;
        tmpl.updatedAt = block.timestamp;

        _templateIdByName[nameHash] = templateId;
        _templatesByCategory[category].push(templateId);
        _activeTemplateIds.push(templateId);

        emit TemplateRegistered(templateId, msg.sender, tmpl.name, tmpl.category, block.timestamp);
    }

    /// @notice Update an existing template
    /// @param templateId The template ID
    /// @param description New description
    /// @param version New version
    /// @param metadataURI New metadata URI
    /// @param bytecodeHash New bytecode hash
    /// @param templateAddress New reference address
    function updateTemplate(
        uint256 templateId,
        string calldata description,
        string calldata version,
        string calldata metadataURI,
        bytes32 bytecodeHash,
        address templateAddress
    ) external {
        if (templateId == 0 || templateId > _templateCount) revert TemplateNotFound(templateId);
        Template storage tmpl = _templates[templateId];
        if (tmpl.author != msg.sender && owner() != msg.sender) revert NotTemplateAuthor(templateId);
        if (tmpl.isDeprecated) revert TemplateDeprecatedError(templateId);

        tmpl.description = description;
        tmpl.version = version;
        tmpl.metadataURI = metadataURI;
        tmpl.bytecodeHash = bytecodeHash;
        tmpl.templateAddress = templateAddress;
        tmpl.updatedAt = block.timestamp;

        emit TemplateUpdated(templateId, tmpl.name, version, block.timestamp);
    }

    /// @notice Deprecate a template (soft-delete)
    /// @param templateId The template ID to deprecate
    function deprecateTemplate(uint256 templateId) external {
        if (templateId == 0 || templateId > _templateCount) revert TemplateNotFound(templateId);
        Template storage tmpl = _templates[templateId];
        if (tmpl.author != msg.sender && owner() != msg.sender) revert NotTemplateAuthor(templateId);
        if (tmpl.isDeprecated) revert TemplateDeprecatedError(templateId);

        tmpl.isDeprecated = true;
        tmpl.isActive = false;
        tmpl.updatedAt = block.timestamp;

        // Remove from active list
        _removeFromActiveList(templateId);

        emit TemplateDeprecated(templateId, block.timestamp);
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    /// @notice Remove a template ID from the active list
    function _removeFromActiveList(uint256 templateId) internal {
        uint256 len = _activeTemplateIds.length;
        for (uint256 i = 0; i < len; i++) {
            if (_activeTemplateIds[i] == templateId) {
                _activeTemplateIds[i] = _activeTemplateIds[len - 1];
                _activeTemplateIds.pop();
                break;
            }
        }
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get template by ID
    /// @param templateId The template ID
    /// @return Template struct
    function getTemplate(uint256 templateId) external view returns (Template memory) {
        if (templateId == 0 || templateId > _templateCount) revert TemplateNotFound(templateId);
        return _templates[templateId];
    }

    /// @notice Get template ID by name
    /// @param name The template name
    /// @return templateId The template ID (0 if not found)
    function getTemplateIdByName(string calldata name) external view returns (uint256) {
        return _templateIdByName[keccak256(bytes(name))];
    }

    /// @notice Get total number of templates
    /// @return count The template count
    function getTemplateCount() external view returns (uint256) {
        return _templateCount;
    }

    /// @notice List all templates (paginated)
    /// @param offset Starting index (0-based)
    /// @param limit Maximum number of results
    /// @return templates Array of Template structs
    function listTemplates(uint256 offset, uint256 limit) external view returns (Template[] memory templates) {
        if (offset >= _templateCount) return new Template[](0);
        uint256 end = offset + limit;
        if (end > _templateCount) end = _templateCount;
        uint256 resultCount = end - offset;
        templates = new Template[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            templates[i] = _templates[offset + i + 1];
        }
    }

    /// @notice List all active (non-deprecated) templates
    /// @return templates Array of active Template structs
    function listActiveTemplates() external view returns (Template[] memory templates) {
        uint256 len = _activeTemplateIds.length;
        templates = new Template[](len);
        for (uint256 i = 0; i < len; i++) {
            templates[i] = _templates[_activeTemplateIds[i]];
        }
    }

    /// @notice List templates by category
    /// @param category The category to filter by
    /// @return templates Array of Template structs in that category
    function listByCategory(string calldata category) external view returns (Template[] memory templates) {
        uint256[] storage ids = _templatesByCategory[category];
        uint256 len = ids.length;
        templates = new Template[](len);
        for (uint256 i = 0; i < len; i++) {
            templates[i] = _templates[ids[i]];
        }
    }

    /// @notice Get all template IDs for a given category
    /// @param category The category
    /// @return ids Array of template IDs
    function getTemplateIdsByCategory(string calldata category) external view returns (uint256[] memory ids) {
        ids = _templatesByCategory[category];
    }
}

contracts/foundry/FoundryTreasurySplitte.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title FoundryTreasurySplitter — Treasury Splitter for X3 Foundry
/// @notice Splits incoming funds according to governance-set percentages using basis points
/// @dev Uses pull-over-push pattern for fund distribution
contract FoundryTreasurySplitter is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Types ────────────────────────────────────────────────────────────────

    /// @notice A single split destination
    struct SplitDestination {
        address payable destination;
        uint256 bps;        // Basis points (e.g., 4000 = 40%)
    }

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Maximum basis points (100%)
    uint256 public constant MAX_BPS = 10000;

    /// @notice Maximum number of split destinations
    uint256 public constant MAX_DESTINATIONS = 20;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Array of split destinations
    SplitDestination[] private _destinations;

    /// @notice Total basis points allocated (must equal MAX_BPS)
    uint256 private _totalBps;

    /// @notice Available native currency balance per destination
    mapping(address => uint256) public availableNative;

    /// @notice Available ERC20 token balance per destination per token
    mapping(address => mapping(address => uint256)) public availableTokens;

    /// @notice Total native currency split all-time
    uint256 public totalNativeSplit;

    /// @notice Total ERC20 tokens split all-time per token
    mapping(address => uint256) public totalTokenSplit;

    // ── Events ───────────────────────────────────────────────────────────────

    /// @notice Emitted when native currency is split
    event NativeSplit(uint256 amount, uint256 timestamp);

    /// @notice Emitted when ERC20 tokens are split
    event TokenSplit(address indexed token, uint256 amount, uint256 timestamp);

    /// @notice Emitted when the split configuration is updated
    event SplitUpdated(uint256 timestamp);

    /// @notice Emitted when a destination claims native funds
    event NativeClaimed(address indexed destination, uint256 amount, uint256 timestamp);

    /// @notice Emitted when a destination claims token funds
    event TokenClaimed(address indexed destination, address indexed token, uint256 amount, uint256 timestamp);

    // ── Errors ───────────────────────────────────────────────────────────────

    error ZeroAddress();
    error InvalidBps(uint256 bps);
    error BpsTotalMismatch(uint256 total, uint256 expected);
    error TooManyDestinations(uint256 count, uint256 max);
    error NoDestinations();
    error NoFundsToClaim();
    error TransferFailed();
    error DuplicateDestination(address dest);

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        _transferOwnership(msg.sender);
    }

    // ── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Set the split configuration (replaces existing)
    /// @param destinations Array of SplitDestination with addresses and BPS
    function setSplit(SplitDestination[] calldata destinations) external onlyOwner {
        if (destinations.length == 0) revert NoDestinations();
        if (destinations.length > MAX_DESTINATIONS) {
            revert TooManyDestinations(destinations.length, MAX_DESTINATIONS);
        }

        uint256 totalBps = 0;
        for (uint256 i = 0; i < destinations.length; i++) {
            if (destinations[i].destination == address(0)) revert ZeroAddress();
            if (destinations[i].bps == 0) revert InvalidBps(0);
            if (destinations[i].bps > MAX_BPS) revert InvalidBps(destinations[i].bps);

            // Check for duplicates
            for (uint256 j = i + 1; j < destinations.length; j++) {
                if (destinations[i].destination == destinations[j].destination) {
                    revert DuplicateDestination(destinations[i].destination);
                }
            }

            totalBps += destinations[i].bps;
        }

        if (totalBps != MAX_BPS) revert BpsTotalMismatch(totalBps, MAX_BPS);

        // Clear existing and set new
        delete _destinations;
        for (uint256 i = 0; i < destinations.length; i++) {
            _destinations.push(destinations[i]);
        }
        _totalBps = totalBps;

        emit SplitUpdated(block.timestamp);
    }

    // ── Core Functions ───────────────────────────────────────────────────────

    /// @notice Split incoming native currency according to the configured splits
    function split() external payable nonReentrant {
        if (msg.value == 0) revert("ZERO_AMOUNT");
        if (_destinations.length == 0) revert NoDestinations();

        uint256 amount = msg.value;
        totalNativeSplit += amount;

        uint256 destLen = _destinations.length;
        for (uint256 i = 0; i < destLen; i++) {
            SplitDestination memory dest = _destinations[i];
            uint256 destAmount = (amount * dest.bps) / MAX_BPS;
            if (destAmount > 0) {
                availableNative[dest.destination] += destAmount;
            }
        }

        emit NativeSplit(amount, block.timestamp);
    }

    /// @notice Split incoming ERC20 tokens according to the configured splits
    /// @param token The ERC20 token address
    /// @param amount The amount of tokens to split
    function splitToken(IERC20 token, uint256 amount) external nonReentrant {
        if (address(token) == address(0)) revert ZeroAddress();
        if (amount == 0) revert("ZERO_AMOUNT");
        if (_destinations.length == 0) revert NoDestinations();

        token.safeTransferFrom(msg.sender, address(this), amount);
        totalTokenSplit[address(token)] += amount;

        uint256 destLen = _destinations.length;
        for (uint256 i = 0; i < destLen; i++) {
            SplitDestination memory dest = _destinations[i];
            uint256 destAmount = (amount * dest.bps) / MAX_BPS;
            if (destAmount > 0) {
                availableTokens[dest.destination][address(token)] += destAmount;
            }
        }

        emit TokenSplit(address(token), amount, block.timestamp);
    }

    // ── Claim Functions (Pull-over-Push) ─────────────────────────────────────

    /// @notice Claim available native currency for the caller
    /// @param amount The amount to claim
    function claimNative(uint256 amount) external nonReentrant {
        if (availableNative[msg.sender] < amount) revert NoFundsToClaim();
        if (amount == 0) revert("ZERO_AMOUNT");

        availableNative[msg.sender] -= amount;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit NativeClaimed(msg.sender, amount, block.timestamp);
    }

    /// @notice Claim all available native currency for the caller
    function claimAllNative() external nonReentrant {
        uint256 amount = availableNative[msg.sender];
        if (amount == 0) revert NoFundsToClaim();

        availableNative[msg.sender] = 0;

        (bool success,) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit NativeClaimed(msg.sender, amount, block.timestamp);
    }

    /// @notice Claim available ERC20 tokens for the caller
    /// @param token The ERC20 token address
    /// @param amount The amount to claim
    function claimToken(address token, uint256 amount) external nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        if (availableTokens[msg.sender][token] < amount) revert NoFundsToClaim();
        if (amount == 0) revert("ZERO_AMOUNT");

        availableTokens[msg.sender][token] -= amount;

        IERC20(token).safeTransfer(msg.sender, amount);

        emit TokenClaimed(msg.sender, token, amount, block.timestamp);
    }

    /// @notice Claim all available ERC20 tokens for the caller
    /// @param token The ERC20 token address
    function claimAllToken(address token) external nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        uint256 amount = availableTokens[msg.sender][token];
        if (amount == 0) revert NoFundsToClaim();

        availableTokens[msg.sender][token] = 0;

        IERC20(token).safeTransfer(msg.sender, amount);

        emit TokenClaimed(msg.sender, token, amount, block.timestamp);
    }

    // ── View Functions ───────────────────────────────────────────────────────

    /// @notice Get the current split configuration
    /// @return destinations Array of SplitDestination
    function getSplit() external view returns (SplitDestination[] memory destinations) {
        destinations = _destinations;
    }

    /// @notice Get the total basis points allocated
    /// @return totalBps The total BPS
    function getTotalBps() external view returns (uint256) {
        return _totalBps;
    }

    /// @notice Get the number of split destinations
    /// @return count The destination count
    function getDestinationCount() external view returns (uint256) {
        return _destinations.length;
    }

    /// @notice Get available native funds for a destination
    /// @param destination The destination address
    /// @return amount Available native currency
    function getAvailableFunds(address destination) external view returns (uint256) {
        return availableNative[destination];
    }

    /// @notice Get available token funds for a destination
    /// @param destination The destination address
    /// @param token The ERC20 token address
    /// @return amount Available tokens
    function getAvailableTokenFunds(address destination, address token) external view returns (uint256) {
        return availableTokens[destination][token];
    }

    /// @notice Get a destination at a specific index
    /// @param index The index
    /// @return SplitDestination struct
    function getDestinationAt(uint256 index) external view returns (SplitDestination memory) {
        return _destinations[index];
    }
}

contracts/governance/CrossChainGovernanc.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../AtlasSphereX3.sol";
import "../WrappedX3.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CrossChainGovernance is Ownable {
    struct Proposal {
        string description;
        uint256 voteStart;
        uint256 voteEnd;
        uint256 forVotes;
        uint256 againstVotes;
        bool executed;
        mapping(address => bool) voted;
    }

    AtlasSphereX3 public immutable x3;
    mapping(uint256 => WrappedX3) public wrappedTokens;
    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    address public immutable treasury;

    event ProposalCreated(uint256 indexed id, string description);
    event Voted(uint256 indexed id, address indexed voter, bool support, uint256 weight);
    event Executed(uint256 indexed id);

    constructor(address x3Token, address treasuryAddr) {
        require(x3Token != address(0), "ZERO_X3");
        require(treasuryAddr != address(0), "ZERO_TREASURY");
        x3 = AtlasSphereX3(x3Token);
        treasury = treasuryAddr;
    }

    function addWrapped(uint256 chainId, address wrapped) external onlyOwner {
        wrappedTokens[chainId] = WrappedX3(wrapped);
    }

    function createProposal(string memory description, uint256 duration) external onlyOwner {
        return _createProposal(description, block.number, duration);
    }

    function createProposalWithStart(
        string memory description,
        uint256 startBlock,
        uint256 duration
    ) external onlyOwner {
        require(startBlock >= block.number, "START_IN_PAST");
        _createProposal(description, startBlock, duration);
    }

    function _createProposal(string memory description, uint256 startBlock, uint256 duration) internal {
        Proposal storage p = proposals[++proposalCount];
        p.description = description;
        p.voteStart = startBlock;
        p.voteEnd = startBlock + duration;
        emit ProposalCreated(proposalCount, description);
    }

    function vote(uint256 id, bool support) external {
        Proposal storage p = proposals[id];
        require(p.voteEnd > 0, "Proposal does not exist");
        require(block.number >= p.voteStart, "Voting not started");
        require(block.number <= p.voteEnd, "Voting closed");
        require(!p.voted[msg.sender], "Already voted");
        uint256 weight = x3.balanceOf(msg.sender);
        for (uint256 i = 0; i < 103; i++) {
            if (address(wrappedTokens[i]) != address(0)) {
                weight += wrappedTokens[i].balanceOf(msg.sender);
            }
        }
        require(weight > 0, "No voting power");
        if (support) p.forVotes += weight;
        else p.againstVotes += weight;
        p.voted[msg.sender] = true;
        emit Voted(id, msg.sender, support, weight);
    }

    function execute(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        require(!p.executed, "Already executed");
        require(block.number > p.voteEnd, "Voting not ended");
        p.executed = true;
        emit Executed(id);
    }
}

