// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title IX3Verification — proof verification interface for X3 cross-chain gateway
/// @notice Deployed on external EVM chains to verify X3 finalized proofs
interface IX3Verification {
    /// @notice Verify an X3 finalized message inclusion proof
    /// @param messageId The keccak256 message identifier
    /// @param sourceChain The X3 chain ID
    /// @param sender The sender on X3 side
    /// @param recipient The recipient on this chain
    /// @param amount The transfer amount
    /// @param proof The X3 finalized block proof (validator signatures or light client proof)
    /// @return verified True if the proof is valid
    function verifyX3WithdrawalProof(
        bytes32 messageId,
        uint256 sourceChain,
        bytes calldata sender,
        address recipient,
        uint256 amount,
        bytes calldata proof
    ) external view returns (bool verified);

    /// @notice Verify a deposit proof from this chain to X3
    /// @param messageId The deposit message identifier
    /// @param token The ERC20 token address
    /// @param depositor The account that deposited tokens
    /// @param x3Recipient The recipient on X3
    /// @param amount The deposit amount
    /// @param proof The deposit proof (receipt or event proof)
    /// @return verified True if the proof is valid
    function verifyDepositProof(
        bytes32 messageId,
        address token,
        address depositor,
        bytes calldata x3Recipient,
        uint256 amount,
        bytes calldata proof
    ) external view returns (bool verified);

    /// @notice Get the current verifier set ID (for rotation tracking)
    function verifierSetId() external view returns (uint256);
}

contracts/staking/StakingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../WrappedX3.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract StakingNFT is ERC721, Ownable {
    uint256 public nextId;
    constructor() ERC721("Staking Position", "sX3NFT") {}
    function mint(address to) external onlyOwner returns (uint256) {
        uint256 id = nextId++;
        _mint(to, id);
        return id;
    }
    function burn(uint256 id) external onlyOwner {
        _burn(id);
    }
}

contract StakingPool is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable stakingToken;
    StakingNFT public immutable stakingNFT;
    address public immutable treasury;
    uint256 public rewardRate; // per block
    uint256 public totalStaked;
    uint256 public lastUpdateBlock;
    uint256 public accRewardPerShare;
    mapping(uint256 => uint256) public stakeAmount;
    mapping(uint256 => uint256) public rewardDebt;
    mapping(address => uint256[]) public userNFTs;

    event Staked(address indexed user, uint256 nftId, uint256 amount);
    event Unstaked(address indexed user, uint256 nftId, uint256 amount);
    event Claimed(address indexed user, uint256 nftId, uint256 reward);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);

    constructor(address stakingToken_, address treasuryAddr) {
        require(stakingToken_ != address(0), "ZERO_STAKING_TOKEN");
        require(treasuryAddr != address(0), "ZERO_TREASURY");
        stakingToken = IERC20(stakingToken_);
        treasury = treasuryAddr;
        stakingNFT = new StakingNFT();
        rewardRate = 1e18; // placeholder
        lastUpdateBlock = block.number;
    }

    function setRewardRate(uint256 rate) external onlyOwner {
        updatePool();
        uint256 oldRate = rewardRate;
        rewardRate = rate;
        emit RewardRateUpdated(oldRate, rate);
    }

    function updatePool() public {
        if (totalStaked == 0) {
            lastUpdateBlock = block.number;
            return;
        }
        uint256 blocks = block.number - lastUpdateBlock;
        accRewardPerShare += (blocks * rewardRate * 1e12) / totalStaked;
        lastUpdateBlock = block.number;
    }

    function stake(uint256 amount) external nonReentrant {
        updatePool();
        stakingToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 nftId = stakingNFT.mint(msg.sender);
        stakeAmount[nftId] = amount;
        rewardDebt[nftId] = (amount * accRewardPerShare) / 1e12;
        userNFTs[msg.sender].push(nftId);
        totalStaked += amount;
        emit Staked(msg.sender, nftId, amount);
    }

    function unstake(uint256 nftId) external nonReentrant {
        require(stakingNFT.ownerOf(nftId) == msg.sender, "Not owner");
        updatePool();
        uint256 amount = stakeAmount[nftId];
        uint256 pending = ((amount * accRewardPerShare) / 1e12) - rewardDebt[nftId];
        delete stakeAmount[nftId];
        delete rewardDebt[nftId];
        totalStaked -= amount;
        stakingToken.safeTransfer(msg.sender, amount);
        if (pending > 0) stakingToken.safeTransfer(msg.sender, pending);
        stakingNFT.burn(nftId);
        emit Unstaked(msg.sender, nftId, amount);
        emit Claimed(msg.sender, nftId, pending);
    }

    function claim(uint256 nftId) external nonReentrant {
        require(stakingNFT.ownerOf(nftId) == msg.sender, "Not owner");
        updatePool();
        uint256 amount = stakeAmount[nftId];
        uint256 pending = ((amount * accRewardPerShare) / 1e12) - rewardDebt[nftId];
        rewardDebt[nftId] = (amount * accRewardPerShare) / 1e12;
        if (pending > 0) stakingToken.safeTransfer(msg.sender, pending);
        emit Claimed(msg.sender, nftId, pending);
    }
}

contracts/treasury/Treasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../AtlasSphereX3.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract Treasury is Ownable, ReentrancyGuard {
    address public immutable devWallet;
    address public immutable daoWallet;
    address public immutable lpWallet;
    uint256 public devSplitBps;
    uint256 public daoSplitBps;
    uint256 public lpSplitBps;
    mapping(address => uint256) public accounting;

    event SplitUpdated(uint256 dev, uint256 dao, uint256 lp);
    event FeeRouted(address indexed from, uint256 amount, string category);

    constructor(address devAddr, address daoAddr, address lpAddr) {
        require(devAddr != address(0), "ZERO_DEV");
        require(daoAddr != address(0), "ZERO_DAO");
        require(lpAddr != address(0), "ZERO_LP");
        devWallet = devAddr;
        daoWallet = daoAddr;
        lpWallet = lpAddr;
        devSplitBps = 2000; // 20%
        daoSplitBps = 5000; // 50%
        lpSplitBps = 3000; // 30%
    }

    function setSplits(uint256 dev, uint256 dao, uint256 lp) external onlyOwner {
        require(dev + dao + lp == 10000, "Must sum to 10000");
        devSplitBps = dev;
        daoSplitBps = dao;
        lpSplitBps = lp;
        emit SplitUpdated(dev, dao, lp);
    }

    function routeFee(address from, uint256 amount, string memory category) external onlyOwner nonReentrant {
        require(from != address(0), "ZERO_FROM");
        require(amount > 0, "ZERO_AMOUNT");
        uint256 devAmt = (amount * devSplitBps) / 10000;
        uint256 daoAmt = (amount * daoSplitBps) / 10000;
        uint256 lpAmt = amount - devAmt - daoAmt;
        accounting[from] += amount;
        (bool devOk, ) = payable(devWallet).call{value: devAmt}("");
        require(devOk, "DEV_TRANSFER_FAILED");
        (bool daoOk, ) = payable(daoWallet).call{value: daoAmt}("");
        require(daoOk, "DAO_TRANSFER_FAILED");
        (bool lpOk, ) = payable(lpWallet).call{value: lpAmt}("");
        require(lpOk, "LP_TRANSFER_FAILED");
        emit FeeRouted(from, amount, category);
    }

    receive() external payable {}
}

